import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  AlertTriangle, BarChart3, BookOpen, Building2, CalendarDays, CalendarRange, CheckCircle2, ChevronDown,
  ClipboardList, Download, Eye, FileSpreadsheet, FileText, Filter, Home, LogOut, PackageCheck, Pencil,
  Plus, Printer, RefreshCw, Save, Search, Settings, ShoppingCart, Sparkles, Target, Trash2, Truck, Upload,
  Users, Warehouse, X, Boxes, Clock3, Image as ImageIcon, KeyRound, ToggleLeft, ToggleRight, Check, Send, Bell, ShieldCheck, ListChecks, Phone, Lock, CheckSquare
} from 'lucide-react';

type User={id:string;email:string;full_name:string;role:string;status:string;institution_id?:string|null;must_change_password?:number;login_code?:string|null};
type Bootstrap={user:User;seasons:any[];grades:any[];publishers:any[];institutions:any[];staff:any[];subjects:string[];permissions:string[]};
const MONTHS=[{v:'09',n:'Eylül'},{v:'10',n:'Ekim'},{v:'11',n:'Kasım'},{v:'12',n:'Aralık'},{v:'01',n:'Ocak'},{v:'02',n:'Şubat'},{v:'03',n:'Mart'},{v:'04',n:'Nisan'},{v:'05',n:'Mayıs'},{v:'06',n:'Haziran'}];
const fmtMoney=(n:any)=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format(Number(n||0)/100);
const fmtDate=(s?:string)=>s?new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${String(s).slice(0,10)}T12:00:00`)):'—';
const fmtShort=(s?:string)=>s?new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'short'}).format(new Date(`${String(s).slice(0,10)}T12:00:00`)):'—';
const monthName=(v?:string)=>MONTHS.find(m=>m.v===v)?.n||'';
const roleName=(r:string)=>({SUPER_ADMIN:'Süper Admin',ADMIN:'Yönetici',PERSONEL:'Satış Personeli',OPERASYON:'Operasyon',KURUM:'Kurum'} as any)[r]||r;
const isAdmin=(u:User)=>['SUPER_ADMIN','ADMIN'].includes(u.role);
const permitted=(boot:Bootstrap,code:string)=>boot.user.role==='SUPER_ADMIN'||(boot.permissions||[]).includes(code);

async function api(path:string,opts:RequestInit={}):Promise<any>{const headers:any={'Content-Type':'application/json',...(opts.headers||{})};const r=await fetch(path,{...opts,headers,credentials:'same-origin'});const data:any=await r.json().catch(()=>({ok:false,error:'Sunucudan geçersiz yanıt'}));if(r.status===401&&path!='/api/auth/login'&&path!='/api/auth/me')location.reload();if(!r.ok||data.ok===false)throw new Error(data.error||'İşlem başarısız');return data}
async function apiForm(path:string,form:FormData):Promise<any>{const r=await fetch(path,{method:'POST',body:form,credentials:'same-origin'});const data:any=await r.json().catch(()=>({ok:false,error:'Sunucudan geçersiz yanıt'}));if(r.status===401)location.reload();if(!r.ok||data.ok===false)throw new Error(data.error||'İşlem başarısız');return data}
function useAsync<T=any>(factory:()=>Promise<T>,deps:any[]=[]){const[data,setData]=useState<T|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState('');const run=async()=>{setLoading(true);setError('');try{setData(await factory())}catch(e:any){setError(e.message||String(e))}finally{setLoading(false)}};useEffect(()=>{run()},deps);return{data,loading,error,reload:run,setData}}

function CosmicLogo({compact=false}:{compact?:boolean}){return <div className={`cosmic-logo ${compact?'compact':''}`} aria-label="Yıldız Yayın"><div className="cosmic-orbit orbit-one"><span className="cosmic-planet planet-one"/><span className="cosmic-book book-one"><BookOpen size={compact?9:12}/></span></div><div className="cosmic-orbit orbit-two"><span className="cosmic-planet planet-two"/><span className="cosmic-book book-two"><BookOpen size={compact?8:11}/></span></div><div className="cosmic-core">★</div></div>}
function BrandLockup({compact=false}:{compact?:boolean}){return <div className={`brand-lockup ${compact?'compact':''}`}><CosmicLogo compact={compact}/><div className="brand-copy"><b>YILDIZ YAYIN</b><span>BASIM DAĞITIM HİZMETLERİ</span><small>Bilginin Yörüngesinde.</small></div></div>}


async function loadDenemeService(){try{return await api('/api/services/deneme/status')}catch{return {enabled:false,can_manage:false}}}
export default function App(){const[user,setUser]=useState<User|null>(null),[boot,setBoot]=useState<Bootstrap|null>(null),[denemeService,setDenemeService]=useState<{enabled:boolean;can_manage:boolean}|null>(null),[checking,setChecking]=useState(true);const load=async()=>{setChecking(true);try{const me=await api('/api/auth/me');setUser(me.user);setBoot(await api('/api/bootstrap'));setDenemeService(await loadDenemeService())}catch{setUser(null);setBoot(null);setDenemeService(null)}finally{setChecking(false)}};useEffect(()=>{load()},[]);if(checking)return <Splash text="Platform hazırlanıyor…"/>;if(!user)return <><FinalCss/><Login onLogin={async u=>{setUser(u);setBoot(await api('/api/bootstrap'));setDenemeService(await loadDenemeService())}}/></>;if(!boot)return <Splash text="Veriler yükleniyor…"/>;return <><FinalCss/><Shell user={user} boot={boot} denemeService={denemeService} refreshBoot={async()=>setBoot(await api('/api/bootstrap'))} onLogout={async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch{}location.reload()}}/></>}
function Splash({text}:{text:string}){return <div className="splash"><BrandLockup/><strong>Yıldız Deneme Platformu</strong><small>{text}</small></div>}
function Login({onLogin}:{onLogin:(u:User)=>void}){const saved=()=>{try{return localStorage.getItem('yd_login_identifier')||''}catch{return ''}};const[idn,setIdn]=useState(saved),[remember,setRemember]=useState(!!saved()),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({identifier:idn,password})});try{remember?localStorage.setItem('yd_login_identifier',idn):localStorage.removeItem('yd_login_identifier')}catch{}onLogin(d.user)}catch(e:any){setError(e.message)}finally{setBusy(false)}};return <div className="login-page"><div className="login-stars"/><div className="login-card"><div className="login-brand"><BrandLockup/><div className="login-product"><h1>Yıldız Deneme</h1><p>Takvim · Sipariş · Tedarik · Teslimat</p></div></div><h2>Platforma giriş yapın</h2><p className="muted">Yönetici/personel e-posta ile, kurumlar kurum kodu ile giriş yapabilir.</p><form onSubmit={submit}><label>E-posta / Kurum Kodu<input value={idn} onChange={e=>setIdn(e.target.value)} required autoFocus autoComplete="username"/></label><label>Şifre<input value={password} onChange={e=>setPassword(e.target.value)} type="password" required autoComplete="current-password"/></label><label className="remember-device"><input type="checkbox" checked={remember} onChange={e=>setRemember(e.target.checked)}/> Bu cihazda e-posta / kurum kodunu hatırla</label><small className="muted">Bu bilgi yalnız bu tarayıcıda saklanır; başka bilgisayar veya telefonda görünmez.</small>{error&&<div className="error-box">{error}</div>}<button className="btn primary wide" disabled={busy}>{busy?'Giriş yapılıyor…':'Giriş Yap'}</button></form><div className="login-foot">Yıldız Yayın Basım Dağıtım Hizmetleri</div></div></div>}

const institutionNav=[
 {key:'dashboard',label:'Ana Sayfa',icon:Home},
 {key:'exams',label:'Denemeler',icon:BookOpen,subs:['Deneme Kataloğu','Takvimim','Cevap Anahtarları']},
 {key:'operations',label:'Operasyon',icon:Truck,subs:['Gelen / Gelecek Denemeler']}
];
const nav=[
 {key:'dashboard',label:'Ana Sayfa',icon:Home},
 {key:'exams',label:'Denemeler',icon:BookOpen,subs:['Deneme Kataloğu','Deneme Takvimi','Cevap Anahtarları']},
 {key:'institutions',label:'Kurumlar',icon:Building2,subs:['Kurumlar','Deneme Planları','Kurum Takvimleri']},
 {key:'sales',label:'Satış',icon:ShoppingCart,subs:['Satış Fırsatları','Sipariş Bekleyenler','Siparişler','Kuruma Sipariş Gir']},
 {key:'publishers',label:'Yayınevleri',icon:Warehouse,subs:['Yayınevleri','Sipariş Listeleri']},
 {key:'operations',label:'Operasyon',icon:Truck,subs:['Tedarik','Gelen Ürünler','Teslimatlar']},
 {key:'reports',label:'Raporlar',icon:BarChart3},
 {key:'management',label:'Yönetim',icon:Settings,roles:['SUPER_ADMIN','ADMIN'],subs:['Kullanıcılar','Yetkiler','Görevler','Sezonlar','Ayarlar','Entegrasyonlar']}
];
function Shell({user,boot,denemeService,refreshBoot,onLogout}:{user:User;boot:Bootstrap;denemeService:{enabled:boolean;can_manage:boolean}|null;refreshBoot:()=>Promise<void>;onLogout:()=>void}){const[section,setSection]=useState('dashboard'),[sub,setSub]=useState(''),[mobile,setMobile]=useState(false);const sectionAllowed=(k:string)=>k==='exams'?(permitted(boot,'CATALOG_VIEW')||permitted(boot,'DIGITAL_VIEW')):k==='institutions'?permitted(boot,'INSTITUTIONS_VIEW'):k==='sales'?(permitted(boot,'OPPORTUNITIES_VIEW')||permitted(boot,'ORDERS_VIEW')||permitted(boot,'ORDERS_CREATE')):k==='publishers'?(permitted(boot,'PUBLISHERS_VIEW')||permitted(boot,'OPERATIONS_VIEW')):k==='operations'?permitted(boot,'OPERATIONS_VIEW'):k==='reports'?permitted(boot,'REPORTS_VIEW'):true;const allowedSub=(k:string,x:string)=>k==='exams'?(x==='Cevap Anahtarları'?permitted(boot,'DIGITAL_VIEW'):permitted(boot,'CATALOG_VIEW')):k==='sales'?(x==='Satış Fırsatları'?permitted(boot,'OPPORTUNITIES_VIEW'):x==='Kuruma Sipariş Gir'?isAdmin(user)&&permitted(boot,'ORDERS_CREATE'):permitted(boot,'ORDERS_VIEW')):k==='publishers'?(x==='Sipariş Listeleri'?permitted(boot,'OPERATIONS_VIEW'):permitted(boot,'PUBLISHERS_VIEW')):true;const subsFor=(n:any)=>(n.subs||[]).filter((x:string)=>allowedSub(n.key,x));const allVisible=user.role==='KURUM'?institutionNav:nav.filter(n=>(!n.roles||n.roles.includes(user.role))&&sectionAllowed(n.key)&&(!n.subs||subsFor(n).length>0));const serviceEnabled=user.role!=='KURUM'||Boolean(denemeService?.enabled);const visible=serviceEnabled?allVisible:allVisible.filter(n=>!['exams','operations'].includes(n.key));useEffect(()=>{if(!visible.some(n=>n.key===section)){setSection('dashboard');setSub('')}},[section,visible.length,serviceEnabled]);const choose=(k:string,s='')=>{const node=(user.role==='KURUM'?institutionNav:nav).find(n=>n.key===k) as any;const ss=node?subsFor(node):[];setSection(k);setSub(s&&ss.includes(s)?s:(ss[0]||''));setMobile(false)};return <><div className="app-shell"><aside className={`sidebar ${mobile?'open':''}`}><div className="brand"><BrandLockup compact/></div><nav>{visible.map(n=>{const I=n.icon;return <div key={n.key}><button className={`nav-main ${section===n.key?'active':''}`} onClick={()=>choose(n.key,subsFor(n)[0]||'')}><I size={19}/><span>{n.label}</span>{n.subs&&<ChevronDown size={14}/>}</button>{section===n.key&&subsFor(n).length>0&&<div className="subnav">{subsFor(n).map((s:string)=><button key={s} className={sub===s?'active':''} onClick={()=>setSub(s)}>{s}</button>)}</div>}</div>})}</nav><div className="sidebar-foot"><div className="user-mini"><div className="avatar">{user.full_name?.[0]||'Y'}</div><div><b>{user.full_name}</b><small>{roleName(user.role)}</small></div></div><button className="icon-btn" onClick={onLogout}><LogOut size={18}/></button></div></aside><main className="main-area"><header className="topbar"><button className="mobile-menu" onClick={()=>setMobile(!mobile)}>☰</button><div><span className="eyebrow">2026–2027 Deneme Sezonu</span><h2>{sub||({dashboard:'Genel Bakış',reports:'Ticari Raporlar'} as any)[section]||'Yıldız Deneme'}</h2></div><div className="top-actions"><MyTasksButton user={user} boot={boot}/><NotificationBell/><span className="status-dot">● Sistem aktif</span></div></header><div className="content">{user.role==='KURUM'?<>{section==='dashboard'&&<InstitutionDashboard boot={boot}/>} {section==='exams'&&(sub==='Takvimim'?<InstitutionCalendar boot={boot} user={user}/>:sub==='Cevap Anahtarları'?<AnswerKeys boot={boot} user={user}/>:<PlanBuilder boot={boot} user={user}/>)} {section==='operations'&&<InstitutionOperations/>}</>:<>{section==='dashboard'&&<Dashboard user={user}/>} {section==='exams'&&<Exams boot={boot} sub={sub} user={user}/>} {section==='institutions'&&<Institutions boot={boot} sub={sub} user={user} refreshBoot={refreshBoot}/>} {section==='sales'&&<Sales boot={boot} sub={sub} user={user}/>} {section==='publishers'&&<Publishers boot={boot} sub={sub} user={user} refreshBoot={refreshBoot}/>} {section==='operations'&&<Operations boot={boot} sub={sub}/>} {section==='reports'&&<Reports/>} {section==='management'&&<Management boot={boot} sub={sub} refreshBoot={refreshBoot}/>}</>}</div></main></div>{user.must_change_password?<ChangePasswordModal/>:null}</>}
function NotificationBell(){const q=useAsync(()=>api('/api/notifications'),[]),[open,setOpen]=useState(false);const items=(q.data as any)?.items||[],unread=items.filter((x:any)=>!x.is_read).length;const read=async(x:any)=>{if(!x.is_read)await api(`/api/notifications/${x.id}/read`,{method:'PATCH'});q.reload()};return <div className="top-pop-wrap"><button className="icon-btn notify-btn" onClick={()=>setOpen(!open)} title="Bildirimler"><Bell size={18}/>{unread>0&&<i>{unread>99?'99+':unread}</i>}</button>{open&&<div className="top-pop"><div className="top-pop-head"><b>Bildirimler</b><small>{unread} okunmamış</small></div>{items.slice(0,20).map((x:any)=><button className={`notice-row ${x.is_read?'':'unread'}`} key={x.id} onClick={()=>read(x)}><b>{x.title}</b><span>{x.message}</span><small>{new Date(x.created_at).toLocaleString('tr-TR')}</small></button>)}{!items.length&&<div className="top-pop-empty">Yeni bildiriminiz yok.</div>}</div>}</div>}
function MyTasksButton({user,boot}:{user:User;boot:Bootstrap}){if(user.role==='KURUM'||!permitted(boot,'TASKS_VIEW'))return null;const q=useAsync(()=>api('/api/tasks'),[]),[open,setOpen]=useState(false);const items=((q.data as any)?.items||[]).filter((x:any)=>x.status!=='DONE');const done=async(x:any)=>{await api(`/api/tasks/${x.id}`,{method:'PATCH',body:JSON.stringify({status:'DONE'})});q.reload()};return <div className="top-pop-wrap"><button className="icon-btn notify-btn" onClick={()=>setOpen(!open)} title="Görevlerim"><ListChecks size={18}/>{items.length>0&&<i>{items.length}</i>}</button>{open&&<div className="top-pop"><div className="top-pop-head"><b>Görevlerim</b><small>{items.length} açık görev</small></div>{items.slice(0,15).map((x:any)=><div className="task-row" key={x.id}><div><b>{x.title}</b><span>{x.description||''}</span><small>{x.due_date?`Son tarih ${fmtDate(x.due_date)}`:'Tarih yok'} · {x.priority||'MEDIUM'}</small></div><button onClick={()=>done(x)} title="Tamamla"><CheckSquare size={16}/></button></div>)}{!items.length&&<div className="top-pop-empty">Açık göreviniz yok.</div>}</div>}</div>}

function ChangePasswordModal(){const[current,setCurrent]=useState(''),[next,setNext]=useState(''),[again,setAgain]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const save=async()=>{setError('');if(next.length<10)return setError('Yeni şifre en az 10 karakter olmalı.');if(next!==again)return setError('Yeni şifreler eşleşmiyor.');setBusy(true);try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({current_password:current,new_password:next})});location.reload()}catch(e:any){setError(e.message)}finally{setBusy(false)}};return <div className="modal-back force"><div className="modal small-modal"><div className="modal-head"><div><span className="eyebrow">Güvenlik</span><h2>Geçici şifrenizi değiştirin</h2></div></div><Field label="Mevcut geçici şifre"><input type="password" value={current} onChange={e=>setCurrent(e.target.value)}/></Field><Field label="Yeni şifre"><input type="password" value={next} onChange={e=>setNext(e.target.value)}/></Field><Field label="Yeni şifre tekrar"><input type="password" value={again} onChange={e=>setAgain(e.target.value)}/></Field>{error&&<div className="error-box">{error}</div>}<button className="btn primary wide" disabled={busy} onClick={save}>Şifremi Değiştir</button></div></div>}

function InstitutionDashboard({boot}:{boot:Bootstrap}){const orders=useAsync(()=>api('/api/orders'),[]),plans=useAsync(()=>{const season=boot.seasons.find(s=>s.is_active)?.id||'';return api(`/api/plans?season_id=${season}`)},[]);if(orders.loading||plans.loading)return <Loading/>;const os=((orders.data as any)?.items||[]).filter((x:any)=>x.status!=='IPTAL'),ps=(plans.data as any)?.items||[];const arrived=os.filter((x:any)=>x.delivered_at),coming=os.filter((x:any)=>!x.delivered_at);return <><div className="institution-hero"><BrandLockup/><div><span className="pill gold"><Sparkles size={14}/> Kurum Deneme Merkezi</span><h1>Denemelerinizi seçin, siparişinizi onaylayın ve teslimatı takip edin.</h1><p>Bu panel yalnız kurumunuzun deneme planı, takvimi, siparişleri ve gelen/gelecek denemelerini gösterir.</p></div></div><div className="kpi-grid"><Kpi icon={CalendarDays} label="Planlanan Deneme" value={ps.length} sub="Kurum takviminizde"/><Kpi icon={ShoppingCart} label="Onaylı Sipariş" value={os.length} sub={`${os.reduce((t:number,x:any)=>t+Number(x.quantity||0),0)} adet`}/><Kpi icon={Truck} label="Gelecek Deneme" value={coming.length} sub="Teslimat bekliyor"/><Kpi icon={PackageCheck} label="Gelen Deneme" value={arrived.length} sub="Kuruma teslim edildi"/></div><Panel title="Yaklaşan siparişleriniz" icon={Clock3}>{coming.length?<DataTable cols={['Sınıf','Yayınevi','Deneme','Adet','Tahmini Sevk','Uygulama']} rows={coming.slice(0,8).map((x:any)=>[x.grade_name,x.publisher_name,x.exam_name,x.quantity,fmtDate(x.estimated_ship_date),`${fmtShort(x.application_start_date)}–${fmtShort(x.application_end_date)}`])}/>:<Empty text="Bekleyen deneme siparişiniz yok."/>}</Panel></>}


function Dashboard({user}:{user:User}){const q=useAsync(()=>api('/api/dashboard'),[]);if(q.loading)return <Loading/>;if(q.error)return <ErrorState text={q.error} retry={q.reload}/>;const d:any=q.data||{};return <><div className="hero"><div><span className="pill gold"><Sparkles size={14}/> Sezon Kontrol Merkezi</span><h1>{user.role==='KURUM'?'Takviminizi ve siparişlerinizi yönetin.':'Deneme sezonunun tamamı tek ekranda.'}</h1><p>{user.role==='KURUM'?'Seçtiğiniz sınavları planlayın, adetleri onaylayın ve teslimatı takip edin.':'Yaklaşan sınavları, acil siparişleri, planlanan satışları ve operasyonu kaçırmayın.'}</p></div><div className="hero-orbit">★</div></div><div className="kpi-grid"><Kpi icon={ShoppingCart} label="Toplam Sipariş" value={d.orders?.total||0} sub={`${d.orders?.quantity||0} adet`}/><Kpi icon={BarChart3} label="Ciro" value={fmtMoney(d.orders?.revenue)} sub={`${d.orders?.pending||0} aktif sipariş`}/><Kpi icon={CalendarDays} label="Yaklaşan Sınav" value={d.upcoming||0} sub="Önümüzdeki 30 gün"/><Kpi icon={Target} label="Satış Fırsatı" value={d.opportunities||0} sub={`${d.plan_pending||0} sipariş bekliyor`}/><Kpi icon={Truck} label="Teslimat Bekliyor" value={d.pending_deliveries||0} sub="Operasyon takibi"/></div><div className="grid-2"><Panel title="Yaklaşan son sipariş tarihleri" icon={Clock3}>{d.deadlines?.length?d.deadlines.map((x:any)=><div className="deadline" key={x.id}><div><b>{x.name}</b><small>{x.publisher} · {x.grade}{x.subject?` · ${x.subject}`:''}</small></div><span>{fmtShort(x.last_order_date)}</span></div>):<Empty text="Yaklaşan kritik tarih yok."/>}</Panel><Panel title="Hızlı kontrol" icon={Sparkles}><ActionRow tone="warn" title={`${d.plan_pending||0} sipariş bekleyen plan`} text="Adedi girilmiş fakat henüz siparişe dönüşmemiş kurum planları."/><ActionRow tone="info" title={`${d.pending_deliveries||0} teslimat tamamlanmadı`} text="Uygulama tarihinden önce teslimatları kapatın."/></Panel></div></>}
function Kpi({icon:I,label,value,sub}:{icon:any;label:string;value:any;sub:string}){return <div className="kpi"><div className="kpi-icon"><I size={20}/></div><span>{label}</span><strong>{value}</strong><small>{sub}</small></div>}
function Panel({title,icon:I,children}:{title:string;icon:any;children:any}){return <section className="panel"><div className="panel-head"><div><I size={18}/><h3>{title}</h3></div></div>{children}</section>}
function ActionRow({tone,title,text}:{tone:string;title:string;text:string}){return <div className={`action-row ${tone}`}><AlertTriangle size={18}/><div><b>{title}</b><small>{text}</small></div></div>}

// EXAMS
function Exams({boot,sub,user}:{boot:Bootstrap;sub:string;user:User}){if(sub==='Cevap Anahtarları')return <AnswerKeys boot={boot} user={user}/>;return sub==='Deneme Takvimi'?<MasterCalendar boot={boot}/>:<ExamCatalog boot={boot} canEdit={isAdmin(user)}/>}
const DIGITAL_TYPES:any={CEVAP_PDF:'Cevap Anahtarı PDF',KAZANIM_EXCEL:'Kazanım Tablosu',DENEME_PDF:'Deneme PDF',OPTIK_DOKUMAN:'Optik Dokümanı',SEKONIC:'Sekonic',BICOM:'Bicom',DIJITAL_FORMAT:'Diğer Dijital Dosya',VIDEO_URL:'Video Çözüm'};
const STAGES=[{key:'ILKOKUL',label:'İlkokul',codes:['1','2','3','4']},{key:'ORTAOKUL',label:'Ortaokul',codes:['5','6','7','8']},{key:'LISE',label:'Lise',codes:['9','10','11','TYT','AYT','YDT']}];
const opticalTypes=new Set(['OPTIK_DOKUMAN','SEKONIC','BICOM']);
function AnswerKeys({boot,user}:{boot:Bootstrap;user:User}){const canManage=user.role==='SUPER_ADMIN';const examsQ=useAsync(()=>canManage?api('/api/exams?active=1'):Promise.resolve({items:[]}),[canManage]);const assetsQ=useAsync(()=>api(`/api/digital-assets${canManage?'?active=all':''}`),[canManage]);const[open,setOpen]=useState<Set<string>>(new Set(['stage:LISE'])),[modal,setModal]=useState<any|null>(null);const toggle=(k:string)=>setOpen(v=>{const n=new Set(v);n.has(k)?n.delete(k):n.add(k);return n});const assets=(assetsQ.data as any)?.items||[];const exams=useMemo(()=>{if(canManage)return (examsQ.data as any)?.items||[];const seen=new Map<string,any>();for(const a of assets)if(!seen.has(a.exam_id))seen.set(a.exam_id,{id:a.exam_id,season_id:a.season_id,grade_level_id:a.grade_level_id,name:a.exam_name,code:a.exam_code,publisher_id:a.publisher_id,publisher_name:a.publisher_name,publisher_short:a.publisher_short,grade_name:a.grade_name,grade_code:a.grade_code});return [...seen.values()]},[canManage,examsQ.data,assetsQ.data]);const publisherLabel=(e:any)=>{const live=boot.publishers.find(p=>p.id===e.publisher_id);return String(live?.short_name||live?.name||e.publisher_short||e.publisher_name||'Yayınevi').trim()};const publisherKey=(e:any)=>publisherLabel(e).toLocaleUpperCase('tr-TR');const reload=()=>assetsQ.reload();const act=async(a:any)=>{await api(`/api/digital-assets/${a.id}`,{method:'PATCH',body:JSON.stringify({is_active:a.is_active?0:1})});reload()};const del=async(a:any)=>{if(!confirm(`${a.title||a.file_name||DIGITAL_TYPES[a.asset_type]} kalıcı olarak silinsin mi?`))return;await api(`/api/digital-assets/${a.id}`,{method:'DELETE'});reload()};if(assetsQ.loading||examsQ.loading)return <Loading/>;return <><div className="archive-hero"><div><span className="pill gold"><FileText size={14}/> Belge Arşivi</span><h2>Cevap Anahtarları</h2><p>İlkokul / Ortaokul / Lise → Yayınevi → Sezon → Sınıf → Deneme → Cevap Anahtarı / Kazanım / Optik Formlar.</p></div>{canManage&&<button className="btn primary" onClick={()=>setModal({})}><Upload size={16}/> Yeni Belge Yükle</button>}</div><div className="archive-tree archive-tree-fixed">{STAGES.map(stage=>{const stageExams=exams.filter((e:any)=>stage.codes.includes(String(e.grade_code||boot.grades.find(g=>g.id===e.grade_level_id)?.code||'')));const pubKeys=[...new Set(stageExams.map((e:any)=>publisherKey(e)))].sort((a:any,z:any)=>String(a).localeCompare(String(z),'tr'));if(!canManage&&!stageExams.length)return null;return <ArchiveFolder key={stage.key} depth={0} label={stage.label} nodeKey={`stage:${stage.key}`} open={open} toggle={toggle} meta={`${stageExams.length} deneme`} icon="school">{pubKeys.map((pk:any)=>{const pubExams=stageExams.filter((e:any)=>publisherKey(e)===pk);const pubName=publisherLabel(pubExams[0]);const seasonIds=[...new Set(pubExams.map((e:any)=>e.season_id))];return <ArchiveFolder key={`${stage.key}:${pk}`} depth={1} label={pubName} nodeKey={`pub:${stage.key}:${pk}`} open={open} toggle={toggle} meta={`${pubExams.length} deneme`} icon="publisher">{seasonIds.sort((a:any,z:any)=>(boot.seasons.find(s=>s.id===z)?.year_start||0)-(boot.seasons.find(s=>s.id===a)?.year_start||0)).map((sid:any)=>{const season=boot.seasons.find(s=>s.id===sid)||{id:sid,name:'Sezon'};const se=pubExams.filter((e:any)=>e.season_id===sid);const gradeIds=[...new Set(se.map((e:any)=>e.grade_level_id))];return <ArchiveFolder key={sid} depth={2} label={season.name} nodeKey={`season:${stage.key}:${pk}:${sid}`} open={open} toggle={toggle} meta="Sezon" icon="season">{gradeIds.sort((a:any,z:any)=>(boot.grades.find(g=>g.id===a)?.sort_order||0)-(boot.grades.find(g=>g.id===z)?.sort_order||0)).map((gid:any)=>{const grade=boot.grades.find(g=>g.id===gid)||se.find((e:any)=>e.grade_level_id===gid)||{};const ge=se.filter((e:any)=>e.grade_level_id===gid).sort((a:any,z:any)=>String(a.application_start_date||'').localeCompare(String(z.application_start_date||''))||String(a.name).localeCompare(String(z.name),'tr'));return <ArchiveFolder key={gid} depth={3} label={grade.name||grade.grade_name||'Sınıf'} nodeKey={`grade:${stage.key}:${pk}:${sid}:${gid}`} open={open} toggle={toggle} meta={`${ge.length} deneme`} icon="grade">{ge.map((e:any)=>{const ef=assets.filter((a:any)=>a.exam_id===e.id);const direct=ef.filter((a:any)=>!opticalTypes.has(a.asset_type));const optical=ef.filter((a:any)=>opticalTypes.has(a.asset_type));const formCodes:string[]=[...new Set<string>(optical.filter((a:any)=>['SEKONIC','BICOM'].includes(a.asset_type)).map((a:any)=>String(a.form_code||'KODSUZ')))].sort();return <ArchiveFolder key={e.id} depth={4} label={e.name} nodeKey={`exam:${e.id}`} open={open} toggle={toggle} meta={e.code} icon="exam" actions={canManage?<button className="tree-add" onClick={ev=>{ev.stopPropagation();setModal({exam_id:e.id})}}><Plus size={13}/> Belge</button>:null}>{direct.map((a:any)=><ArchiveFile key={a.id} a={a} depth={5} canManage={canManage} edit={()=>setModal({item:a,exam_id:e.id})} toggleActive={()=>act(a)} remove={()=>del(a)}/>)}{optical.length>0&&<ArchiveFolder depth={5} label="Optik Dokümanları / Formları" nodeKey={`optical:${e.id}`} open={open} toggle={toggle} meta={`${optical.length} dosya`} icon="optical">{optical.filter((a:any)=>a.asset_type==='OPTIK_DOKUMAN').map((a:any)=><ArchiveFile key={a.id} a={a} depth={6} canManage={canManage} edit={()=>setModal({item:a,exam_id:e.id})} toggleActive={()=>act(a)} remove={()=>del(a)}/>)}{formCodes.map(code=><ArchiveFolder key={code} depth={6} label={`Form Kodu: ${code}`} nodeKey={`form:${e.id}:${code}`} open={open} toggle={toggle} meta="Sekonic / Bicom" icon="form">{optical.filter((a:any)=>String(a.form_code||'KODSUZ')===code&&['SEKONIC','BICOM'].includes(a.asset_type)).sort((a:any,z:any)=>a.asset_type.localeCompare(z.asset_type)).map((a:any)=><ArchiveFile key={a.id} a={a} depth={7} canManage={canManage} edit={()=>setModal({item:a,exam_id:e.id})} toggleActive={()=>act(a)} remove={()=>del(a)} directLabel={a.asset_type==='SEKONIC'?'Sekonic':'Bicom'}/>)}</ArchiveFolder>)}</ArchiveFolder>}{!ef.length&&canManage&&<div className="tree-empty" style={{paddingLeft:182}}>Henüz belge yüklenmemiş.</div>}</ArchiveFolder>})}</ArchiveFolder>})}</ArchiveFolder>})}</ArchiveFolder>})}</ArchiveFolder>})}</div>{modal&&<DigitalAssetModal exams={exams} item={modal.item||null} initialExam={modal.exam_id||''} close={()=>setModal(null)} saved={()=>{setModal(null);reload()}}/>}</>}
function ArchiveFolder({depth,label,nodeKey,open,toggle,meta,icon,actions,children}:{depth:number;label:string;nodeKey:string;open:Set<string>;toggle:(k:string)=>void;meta?:string;icon?:string;actions?:any;children:any}){const isOpen=open.has(nodeKey);return <div className="tree-node"><div className={`tree-folder depth-${Math.min(depth,7)}`} style={{paddingLeft:14+depth*24}} onClick={()=>toggle(nodeKey)} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle(nodeKey)}}}><span className={`tree-caret ${isOpen?'open':''}`}>›</span><span className={`tree-folder-icon ${icon||''}`}>📁</span><b>{label}</b>{meta&&<small>{meta}</small>}<span className="tree-spacer"/>{actions}</div>{isOpen&&<div className="tree-children">{children}</div>}</div>}
function ArchiveFile({a,depth,canManage,edit,toggleActive,remove,directLabel}:{a:any;depth:number;canManage:boolean;edit:()=>void;toggleActive:()=>void;remove:()=>void;directLabel?:string}){const label=directLabel||a.title||DIGITAL_TYPES[a.asset_type]||a.asset_type;const href=a.external_url||`/api/digital-assets/${a.id}/download`;return <div className={`tree-file ${a.is_active?'':'inactive'}`} style={{paddingLeft:38+depth*24}}><a href={href} target={a.external_url?'_blank':undefined} rel="noreferrer" title="İndir / Aç"><span className="tree-file-icon">{a.asset_type==='KAZANIM_EXCEL'?'▣':'☁'}</span><b>{label}</b><small>{a.file_name||a.format_name||a.external_url||''}</small>{a.form_code&&<em>{a.form_code}</em>}</a>{canManage&&<Actions><Badge text={a.is_active?'Aktif':'Pasif'} tone={a.is_active?'good':'muted'}/><button onClick={edit} title="Düzenle / dosyayı değiştir"><Pencil size={14}/></button><button onClick={toggleActive} title={a.is_active?'Pasif yap':'Aktif yap'}>{a.is_active?<ToggleRight size={16}/>:<ToggleLeft size={16}/>}</button><button className="danger" onClick={remove} title="Sil"><Trash2 size={14}/></button></Actions>}</div>}
function DigitalAssetModal({exams,item,initialExam,close,saved}:{exams:any[];item?:any|null;initialExam?:string;close:()=>void;saved:()=>void}){const[b,setB]=useState<any>(item?{...item}:{exam_id:initialExam||exams[0]?.id||'',asset_type:'CEVAP_PDF',is_active:1}),[file,setFile]=useState<File|null>(null);const isForm=['SEKONIC','BICOM'].includes(b.asset_type);const save=async()=>{if(isForm&&!String(b.form_code||'').trim())throw new Error('Sekonic/Bicom için optik form kodu zorunlu.');if(!item){const f=new FormData();for(const k of ['exam_id','asset_type','title','format_name','form_code','external_url'])if(b[k])f.append(k,String(b[k]));if(file)f.append('file',file);await apiForm('/api/digital-assets',f)}else{await api(`/api/digital-assets/${item.id}`,{method:'PATCH',body:JSON.stringify({asset_type:b.asset_type,title:b.title||null,format_name:b.format_name||null,form_code:b.form_code||null,external_url:b.external_url||null,is_active:b.is_active?1:0})});if(file){const f=new FormData();f.append('file',file);await apiForm(`/api/digital-assets/${item.id}/replace`,f)}}saved()};return <Modal title={item?'Belgeyi düzenle / değiştir':'Yeni belge yükle'} close={close}><FormGrid><Field label="Deneme"><select value={b.exam_id||''} disabled={!!item} onChange={e=>setB({...b,exam_id:e.target.value})}><option value="">Seçiniz</option>{exams.map((x:any)=><option key={x.id} value={x.id}>{x.publisher_short||x.publisher_name} · {x.grade_name} · {x.name}</option>)}</select></Field><Field label="Belge türü"><select value={b.asset_type} disabled={!!item} onChange={e=>setB({...b,asset_type:e.target.value})}>{Object.entries(DIGITAL_TYPES).map(([k,v]:any)=><option value={k} key={k}>{v}</option>)}</select></Field><Field label="Başlık"><input value={b.title||''} onChange={e=>setB({...b,title:e.target.value})} placeholder={DIGITAL_TYPES[b.asset_type]}/></Field>{isForm&&<Field label="Optik form kodu"><input value={b.form_code||''} onChange={e=>setB({...b,form_code:e.target.value.toUpperCase()})} placeholder="Örn. F001 / TYT-01"/></Field>}{b.asset_type==='OPTIK_DOKUMAN'&&<Field label="Form kodu (isteğe bağlı)"><input value={b.form_code||''} onChange={e=>setB({...b,form_code:e.target.value.toUpperCase()})}/></Field>}{b.asset_type==='DIJITAL_FORMAT'&&<Field label="Format adı"><input value={b.format_name||''} onChange={e=>setB({...b,format_name:e.target.value})} placeholder="Örn. XML / CSV / cihaz formatı"/></Field>}{b.asset_type==='VIDEO_URL'?<Field label="Video bağlantısı"><input type="url" value={b.external_url||''} onChange={e=>setB({...b,external_url:e.target.value})} placeholder="https://..."/></Field>:<Field label={item?'Yeni dosya (değiştirmek istemezseniz boş bırakın)':'Dosya'}><input type="file" onChange={e=>setFile(e.target.files?.[0]||null)} accept={b.asset_type==='CEVAP_PDF'||b.asset_type==='DENEME_PDF'||b.asset_type==='OPTIK_DOKUMAN'?'.pdf':b.asset_type==='KAZANIM_EXCEL'?'.xlsx,.xls,.csv':b.asset_type==='SEKONIC'?'.fmt,.txt,.dat,.xml,.csv':'*/*'}/></Field>}{item&&<label className="check"><input type="checkbox" checked={!!b.is_active} onChange={e=>setB({...b,is_active:e.target.checked?1:0})}/> Aktif</label>}</FormGrid><div className="info-box">Kurum ve personel kullanıcıları bu arşivde yalnız görüntüleme ve indirme yapabilir. Yükleme, değiştirme, aktif/pasif ve silme işlemleri yalnız Süper Admin'e açıktır.</div><ModalActions close={close} save={save}/></Modal>}

function ExamCatalog({boot,canEdit}:{boot:Bootstrap;canEdit:boolean}){const[season,setSeason]=useState(boot.seasons.find(s=>s.is_active)?.id||boot.seasons[0]?.id||''),[grade,setGrade]=useState(''),[active,setActive]=useState('1'),[publisher,setPublisher]=useState(''),[month,setMonth]=useState(''),[q,setQ]=useState(''),[edit,setEdit]=useState<any|null>(null),[bulk,setBulk]=useState(false);const list=useAsync(()=>api(`/api/exams?season_id=${season}${grade?`&grade_level_id=${grade}`:''}${publisher?`&publisher_id=${publisher}`:''}${month?`&month=${month}`:''}${active?`&active=${active}`:''}${q?`&q=${encodeURIComponent(q)}`:''}`),[season,grade,publisher,month,active,q]);const items=(list.data as any)?.items||[];const remove=async(x:any)=>{if(!confirm(`${x.name} kaydını silmek/pasife almak istiyor musunuz?`))return;await api(`/api/exams/${x.id}`,{method:'DELETE'});list.reload()};const toggle=async(x:any)=>{await api(`/api/exams/${x.id}`,{method:'PATCH',body:JSON.stringify({is_active:!x.is_active})});list.reload()};const exportXlsx=async()=>{const XLSX=await import('xlsx');const rows=items.map((x:any)=>({publisher:x.publisher_name,grade:x.grade_code,exam_type:x.exam_type||'DENEME',difficulty_level:x.difficulty_level||'',subject:x.subject||'',name:x.name,code:x.code,last_order_date:x.last_order_date||'',estimated_ship_date:x.estimated_ship_date||'',application_start_date:x.application_start_date||'',application_end_date:x.application_end_date||'',list_price:Number(x.list_price||0)/100,purchase_price:Number(x.purchase_price||0)/100,sale_price:Number(x.default_sale_price||0)/100,minimum_order:x.minimum_order,active:x.is_active?'evet':'hayır'}));const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Denemeler');XLSX.writeFile(wb,'Yildiz-Deneme-Katalogu.xlsx')};return <><div className="info-box"><b>Deneme Kataloğu</b><div>Sezon, sınıf, durum, yayınevi, ay ve arama filtrelerini birlikte kullanabilirsiniz. Filtreler tüm kullanıcı rollerinde aynı yerde çalışır; işlem butonları kullanıcı yetkisine göre gösterilir.</div></div><Toolbar><select title="Sezon" value={season} onChange={e=>setSeason(e.target.value)}>{boot.seasons.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select><select title="Sınıf" value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{boot.grades.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select><select title="Durum" value={active} onChange={e=>setActive(e.target.value)}><option value="1">Aktif</option><option value="0">Pasif</option><option value="">Tümü</option></select><select title="Yayınevi" value={publisher} onChange={e=>setPublisher(e.target.value)}><option value="">Tüm yayınevleri</option>{boot.publishers.filter(p=>p.is_active!==0).map(p=><option value={p.id} key={p.id}>{p.short_name||p.name}</option>)}</select><select title="Ay" value={month} onChange={e=>setMonth(e.target.value)}><option value="">Tüm aylar</option>{MONTHS.map(m=><option key={m.v} value={m.v}>{m.n}</option>)}</select><SearchBox value={q} set={setQ}/><button className="btn" onClick={()=>{setGrade('');setActive('1');setPublisher('');setMonth('');setQ('')}}><RefreshCw size={15}/> Filtreleri Temizle</button><span className="selection-count">Gösterilen <b>{items.length}</b></span><div className="spacer"/>{canEdit&&<button className="btn" onClick={()=>setBulk(true)}><Upload size={16}/> İçe Aktar</button>}<button className="btn" onClick={exportXlsx}><Download size={16}/> Dışa Aktar</button>{canEdit&&<button className="btn primary" onClick={()=>setEdit({})}><Plus size={16}/> Deneme Ekle</button>}</Toolbar>{list.loading?<Loading/>:<DataTable cols={['Tarih','Sınıf','Tür','Zorluk','Yayınevi','Deneme','Kod','Son Sipariş','Satış','Durum','İşlem']} rows={items.map((x:any)=>[fmtShort(x.application_start_date),x.grade_name,x.exam_type==='DERS_SINAVI'?`Ders · ${x.subject||'—'}`:(x.exam_type||'Deneme'),x.difficulty_level||'—',x.publisher_short||x.publisher_name,x.name,x.code,fmtDate(x.last_order_date),fmtMoney(x.default_sale_price),<Badge key="b" text={x.is_active?'Aktif':'Pasif'} tone={x.is_active?'good':'muted'}/>,canEdit?<Actions key="a"><button onClick={()=>setEdit(x)} title="Düzenle"><Pencil size={15}/></button><button onClick={()=>toggle(x)} title={x.is_active?'Pasif yap':'Aktif yap'}>{x.is_active?<ToggleRight size={17}/>:<ToggleLeft size={17}/>}</button><button className="danger" onClick={()=>remove(x)} title="Sil/Pasife al"><Trash2 size={15}/></button></Actions>:'—'])}/>} {edit&&<ExamModal boot={boot} season={season} item={edit.id?edit:null} close={()=>setEdit(null)} saved={()=>{setEdit(null);list.reload()}}/>}{bulk&&<ExamBulkModal boot={boot} season={season} close={()=>setBulk(false)} saved={()=>{setBulk(false);list.reload()}}/>}</>}
function ExamModal({boot,season,item,close,saved}:{boot:Bootstrap;season:string;item:any|null;close:()=>void;saved:()=>void}){const[b,setB]=useState<any>(item?{...item,list_price:Number(item.list_price||0)/100,purchase_price:Number(item.purchase_price||0)/100,default_sale_price:Number(item.default_sale_price||0)/100}:{season_id:season,publisher_id:boot.publishers[0]?.id,grade_level_id:boot.grades[0]?.id,minimum_order:1,exam_type:'DENEME',difficulty_level:'',is_active:1});const save=async()=>{const payload={...b,list_price:Math.round(Number(b.list_price||0)*100),purchase_price:Math.round(Number(b.purchase_price||0)*100),default_sale_price:Math.round(Number(b.default_sale_price||0)*100),subject:b.exam_type==='DERS_SINAVI'?b.subject||null:b.subject||null,difficulty_level:String(b.difficulty_level||'').trim()||null};await api(item?`/api/exams/${item.id}`:'/api/exams',{method:item?'PATCH':'POST',body:JSON.stringify(payload)});saved()};return <Modal title={item?'Denemeyi düzenle':'Yeni sınav / deneme'} close={close}><FormGrid><Field label="Yayınevi"><select value={b.publisher_id||''} onChange={e=>setB({...b,publisher_id:e.target.value})}>{boot.publishers.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></Field><Field label="Sınıf düzeyi"><select value={b.grade_level_id||''} onChange={e=>setB({...b,grade_level_id:e.target.value})}>{boot.grades.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></Field><Field label="Sınav türü / seri"><input value={b.exam_type||''} onChange={e=>setB({...b,exam_type:e.target.value})} placeholder="DENEME / TÜRKİYE GENELİ / 1. DENEME"/></Field><Field label="Zorluk seviyesi (isteğe bağlı)"><input list="difficulty-levels" value={b.difficulty_level||''} onChange={e=>setB({...b,difficulty_level:e.target.value})} placeholder="KOLAY / ORTA / ZOR"/><datalist id="difficulty-levels"><option value="KOLAY"/><option value="KOLAY-ORTA"/><option value="ORTA"/><option value="ORTA-ÜST"/><option value="ORTA-ZOR"/><option value="ZOR"/><option value="YKS SINAV DÜZEYİ"/><option value="YKS SINAV AYARI"/><option value="MAARİF"/><option value="TG"/></datalist></Field>{String(b.exam_type||'').toUpperCase()==='DERS_SINAVI'&&<Field label="Ders"><select value={b.subject||''} onChange={e=>setB({...b,subject:e.target.value})}><option value="">Seçiniz</option>{boot.subjects.map(s=><option key={s}>{s}</option>)}</select></Field>}<Field label="Sınav / deneme adı"><input value={b.name||''} onChange={e=>setB({...b,name:e.target.value})}/></Field><Field label="Kod"><input value={b.code||''} onChange={e=>setB({...b,code:e.target.value})}/></Field><Field label="Son sipariş"><input type="date" value={b.last_order_date||''} onChange={e=>setB({...b,last_order_date:e.target.value})}/></Field><Field label="Tahmini sevk"><input type="date" value={b.estimated_ship_date||''} onChange={e=>setB({...b,estimated_ship_date:e.target.value})}/></Field><Field label="Uygulama başlangıcı"><input type="date" value={b.application_start_date||''} onChange={e=>setB({...b,application_start_date:e.target.value})}/></Field><Field label="Uygulama bitişi"><input type="date" value={b.application_end_date||''} onChange={e=>setB({...b,application_end_date:e.target.value})}/></Field><Field label="Liste fiyatı (TL)"><input type="number" value={b.list_price||''} onChange={e=>setB({...b,list_price:e.target.value})}/></Field><Field label="Alış fiyatı (TL)"><input type="number" value={b.purchase_price||''} onChange={e=>setB({...b,purchase_price:e.target.value})}/></Field><Field label="Satış fiyatı (TL)"><input type="number" value={b.default_sale_price||''} onChange={e=>setB({...b,default_sale_price:e.target.value})}/></Field><Field label="Minimum sipariş"><input type="number" value={b.minimum_order||1} onChange={e=>setB({...b,minimum_order:e.target.value})}/></Field></FormGrid><ModalActions close={close} save={save}/></Modal>}
function ExamBulkModal({boot,season,close,saved}:{boot:Bootstrap;season:string;close:()=>void;saved:()=>void}){const[rows,setRows]=useState<any[]>([]),[errors,setErrors]=useState<any[]>([]),[busy,setBusy]=useState(false),[summary,setSummary]=useState('');const template=async()=>{const XLSX=await import('xlsx');const sample=[{publisher:'Demo Yayınları',grade:'TYT',exam_type:'1. DENEME',difficulty_level:'ORTA',subject:'',name:'TYT Kurumsal Deneme',code:'DEMO-TYT-01',last_order_date:'2026-09-01',estimated_ship_date:'2026-09-05',application_start_date:'2026-09-10',application_end_date:'2026-09-12',list_price:150,purchase_price:90,sale_price:120,minimum_order:10,active:'evet'}];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(sample),'Şablon');const notes=[['Alan','Açıklama'],['Maksimum','Tek dosyada 2.000 satır'],['difficulty_level','İsteğe bağlı: KOLAY, ORTA, ZOR vb. Serbest metin kabul edilir.'],['subject','Ders sınavında ders; genel denemede boş bırakılabilir.'],['active','evet/hayır; boşsa evet'],['Tekrar kayıt','Aynı sezon + aynı code varsa mevcut kayıt güncellenir.'],['Yayınevi','Sistemde yoksa temel yayınevi kaydı otomatik oluşturulur.']];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(notes),'Açıklama');XLSX.writeFile(wb,'Deneme-Yukleme-Sablonu.xlsx')};const headerKey=(v:any)=>String(v??'').trim().toLocaleLowerCase('tr-TR').replace(/[ıİ]/g,'i').replace(/[şŞ]/g,'s').replace(/[ğĞ]/g,'g').replace(/[üÜ]/g,'u').replace(/[öÖ]/g,'o').replace(/[çÇ]/g,'c').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');const pick=(o:any,...names:string[])=>{const m:any={};Object.entries(o).forEach(([k,v])=>m[headerKey(k)]=v);for(const n of names){const k=headerKey(n);if(m[k]!==undefined&&m[k]!==null&&m[k]!=='')return m[k]}return ''};const dateValue=(v:any,XLSX:any)=>{if(v===null||v===undefined||v==='')return '';if(v instanceof Date&&!isNaN(v.getTime()))return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;if(typeof v==='number'){const d=XLSX.SSF.parse_date_code(v);if(d)return `${String(d.y).padStart(4,'0')}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`}const s=String(v).trim();const iso=s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);if(iso)return `${iso[1]}-${iso[2].padStart(2,'0')}-${iso[3].padStart(2,'0')}`;const tr=s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})$/);if(tr){let y=tr[3];if(y.length===2)y=`20${y}`;return `${y}-${tr[2].padStart(2,'0')}-${tr[1].padStart(2,'0')}`}return s};const isDifficulty=(v:any)=>/^(KOLAY|KOLAY[- ]?ORTA|ORTA|ORTA[- ]?(ÜST|ZOR)|ZOR|YKS|MAARİF|TG)/i.test(String(v||'').trim());const normalizeRow=(o:any,XLSX:any)=>{const examType=String(pick(o,'exam_type','sınav türü','sinav turu','tür','tur')||'DENEME').trim();let subject=String(pick(o,'subject','ders')||'').trim();let difficulty=String(pick(o,'difficulty_level','difficulty','zorluk','zorluk seviyesi','zorluk_seviyesi')||'').trim();if(!difficulty&&subject&&String(examType).toUpperCase()!=='DERS_SINAVI'&&isDifficulty(subject)){difficulty=subject;subject=''}const emptyKey=Object.keys(o).find(k=>k.startsWith('__EMPTY'));const active=pick(o,'active','aktif')|| (emptyKey?o[emptyKey]:'');return {publisher:String(pick(o,'publisher','yayınevi','yayinevi')||'').trim(),grade:String(pick(o,'grade','sınıf','sinif','sınıf düzeyi','sinif duzeyi')||'').trim(),exam_type:examType,difficulty_level:difficulty,subject,name:String(pick(o,'name','deneme','sınav','sinav','sınav adı','sinav adi')||'').trim(),code:String(pick(o,'code','kod')||'').trim(),last_order_date:dateValue(pick(o,'last_order_date','son sipariş','son siparis'),XLSX),estimated_ship_date:dateValue(pick(o,'estimated_ship_date','sevk','tahmini sevk'),XLSX),application_start_date:dateValue(pick(o,'application_start_date','uygulama başlangıç','uygulama baslangic'),XLSX),application_end_date:dateValue(pick(o,'application_end_date','uygulama bitiş','uygulama bitis'),XLSX),list_price:pick(o,'list_price','liste fiyatı','liste fiyati'),purchase_price:pick(o,'purchase_price','alış fiyatı','alis fiyati'),sale_price:pick(o,'sale_price','satış fiyatı','satis fiyati','default_sale_price'),minimum_order:pick(o,'minimum_order','minimum sipariş','minimum siparis')||1,active:active||'evet'}};const validate=(items:any[])=>{const es:any[]=[];if(items.length>2000)es.push({row:0,error:`Tek dosyada en fazla 2000 satır yüklenebilir. Bu dosyada ${items.length} satır var.`});const seen=new Map<string,number>();items.slice(0,2000).forEach((x:any,i)=>{const row=i+2;if(!x.publisher)es.push({row,error:'Yayınevi boş olamaz.'});if(!x.grade)es.push({row,error:'Sınıf düzeyi boş olamaz.'});if(!x.name)es.push({row,error:'Deneme adı boş olamaz.'});if(!x.code)es.push({row,error:'Kod boş olamaz.'});const key=String(x.code||'').trim().toLocaleUpperCase('tr-TR');if(key){if(seen.has(key))es.push({row,error:`Aynı dosyada tekrar eden kod: ${x.code} (ilk satır ${seen.get(key)})`});else seen.set(key,row)}});return es};const file=async(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(!f)return;setSummary('');const XLSX=await import('xlsx');const wb=XLSX.read(await f.arrayBuffer(),{cellDates:true});const raw=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:'',raw:true}) as any[];const normalized=raw.filter((o:any)=>Object.values(o).some(v=>String(v??'').trim()!=='')).map(o=>normalizeRow(o,XLSX));const es=validate(normalized);setRows(normalized.slice(0,2000));setErrors(es)};const upload=async()=>{setBusy(true);setSummary('');try{const d=await api('/api/exams/bulk',{method:'POST',body:JSON.stringify({season_id:season,rows})});setErrors(d.errors||[]);setSummary(`${d.created||0} yeni, ${d.updated||0} güncellendi${d.publishers_created?`, ${d.publishers_created} yeni yayınevi oluşturuldu`:''}.`);if(!(d.errors||[]).length)setTimeout(()=>saved(),450)}finally{setBusy(false)}};return <Modal title="Toplu sınav / deneme yükle · 2.000 satır" close={close}><div className="bulk-head"><button className="btn" onClick={template}><FileSpreadsheet size={16}/> Güncel şablonu indir</button><label className="btn"><Upload size={16}/> Excel seç<input hidden type="file" accept=".xlsx,.xls,.csv" onChange={file}/></label></div><div className="info-box">Tek dosyada en fazla <b>2.000 sınav</b>. Excel tarihleri otomatik çevrilir. Zorluk seviyesi isteğe bağlıdır. Eski şablonda <b>subject</b> sütununa yazılmış KOLAY/ORTA/ZOR benzeri değerler de otomatik olarak zorluk seviyesi kabul edilir.</div><p className="muted">{rows.length} satır okundu. Yayınevi sistemde yoksa otomatik temel kayıt açılır; aynı sezon + aynı kod varsa mevcut deneme güncellenir.</p>{rows.length>0&&<DataTable cols={['#','Yayınevi','Sınıf','Tür','Zorluk','Ad','Kod']} rows={rows.slice(0,10).map((x:any,i)=>[i+2,x.publisher,x.grade,x.exam_type,x.difficulty_level||'—',x.name,x.code])}/>} {errors.length>0&&<div className="error-box">{errors.slice(0,30).map((x:any,i)=><div key={`${x.row}-${i}`}>{x.row?`Satır ${x.row}: `:''}{x.error}</div>)}{errors.length>30&&<div>+ {errors.length-30} hata daha</div>}</div>}{summary&&<div className="success-box"><CheckCircle2 size={18}/>{summary}</div>}<div className="modal-actions"><button className="btn" onClick={close}>Vazgeç</button><button className="btn primary" disabled={!rows.length||busy||errors.length>0} onClick={upload}>{busy?'Yükleniyor…':`${rows.length} satırı yükle`}</button></div></Modal>}
function MasterCalendar({boot}:{boot:Bootstrap}){const[season,setSeason]=useState(boot.seasons.find(s=>s.is_active)?.id||''),[grade,setGrade]=useState('');const q=useAsync(()=>api(`/api/exams?season_id=${season}&active=1${grade?`&grade_level_id=${grade}`:''}`),[season,grade]);const grouped=useMemo(()=>groupByMonth((q.data as any)?.items||[],'application_start_date'),[q.data]);return <><Toolbar><select value={season} onChange={e=>setSeason(e.target.value)}>{boot.seasons.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select><select value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{boot.grades.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></Toolbar><div className="season-board">{MONTHS.map(m=><div className="month-card" key={m.v}><h3>{m.n}</h3>{(grouped[m.v]||[]).map((x:any)=><div className="exam-event" key={x.id}><span>{fmtShort(x.application_start_date)}</span><b>{x.grade_name} · {x.publisher_short}</b><small>{x.name}</small><em>Son sipariş {fmtShort(x.last_order_date)}</em></div>)}{!(grouped[m.v]||[]).length&&<small className="muted">Planlı sınav yok</small>}</div>)}</div></>}
function groupByMonth(items:any[],key:string){return items.reduce((a:any,x:any)=>{const d=x[key];if(d){const m=String(d).slice(5,7);(a[m]||=[]).push(x)}return a},{})}

// INSTITUTIONS
function Institutions({boot,sub,user,refreshBoot}:{boot:Bootstrap;sub:string;user:User;refreshBoot:()=>Promise<void>}){if(sub==='Deneme Planları')return <PlanBuilder boot={boot} user={user}/>;if(sub==='Kurum Takvimleri')return <InstitutionCalendar boot={boot} user={user}/>;return <InstitutionList boot={boot} user={user} refreshBoot={refreshBoot}/>}
function InstitutionList({boot,user,refreshBoot}:{boot:Bootstrap;user:User;refreshBoot:()=>Promise<void>}) {
  const [q,setQ]=useState(''),[active,setActive]=useState('1'),[edit,setEdit]=useState<any|null>(null),[erp,setErp]=useState(false),[serviceBusy,setServiceBusy]=useState('');
  const list=useAsync(()=>api(`/api/institutions?active=${active}${q?`&q=${encodeURIComponent(q)}`:''}`),[q,active]);
  const service=useAsync(()=>isAdmin(user)?api('/api/services/deneme/institutions'):Promise.resolve({items:[]}),[user.role]);
  const items=(list.data as any)?.items||[];
  const serviceById=Object.fromEntries(((service.data as any)?.items||[]).map((x:any)=>[x.id,x]));
  const remove=async(x:any)=>{if(!confirm(`${x.name} silinsin/pasife alınsın mı?`))return;await api(`/api/institutions/${x.id}`,{method:'DELETE'});list.reload()};
  const toggle=async(x:any)=>{await api(`/api/institutions/${x.id}`,{method:'PATCH',body:JSON.stringify({is_active:!x.is_active})});list.reload();refreshBoot()};
  const toggleDeneme=async(x:any)=>{
    const current=serviceById[x.id];setServiceBusy(x.id);
    try{await api(`/api/services/deneme/institutions/${x.id}`,{method:'PUT',body:JSON.stringify({enabled:!(Number(current?.enabled||0)===1)})});await service.reload()}
    catch(e:any){alert(e.message)}
    finally{setServiceBusy('')}
  };
  return <>
    <Toolbar><SearchBox value={q} set={setQ}/><select value={active} onChange={e=>setActive(e.target.value)}><option value="1">Aktif</option><option value="0">Pasif</option><option value="">Tümü</option></select><div className="spacer"/>{isAdmin(user)&&<><button className="btn" onClick={()=>setErp(true)}><RefreshCw size={16}/> ERP'den Cari Seç</button><button className="btn primary" onClick={()=>setEdit({})}><Plus size={16}/> Kurum Ekle</button></>}</Toolbar>
    {isAdmin(user)&&<div className="service-access-note"><ShieldCheck size={17}/><div><strong>Deneme Servisi erişimi</strong><span>Kapalı kurumlar deneme takvimini ve sipariş hizmetini göremez. Açma/kapatma yalnızca bu kurum listesinde yapılır.</span></div></div>}
    <DataTable cols={['Kurum','Kod','Tür','İlçe','Yetkili','Sorumlu','Kapasite','Giriş','Durum',...(isAdmin(user)?['Deneme Servisi']:[]),'İşlem']} rows={items.map((x:any)=>{
      const access=serviceById[x.id],enabled=Number(access?.enabled||0)===1;
      const serviceCell=isAdmin(user)?<button className={`service-toggle ${enabled?'enabled':'disabled'}`} onClick={()=>void toggleDeneme(x)} disabled={serviceBusy===x.id} aria-pressed={enabled}><span className="service-toggle-dot"/><span>{serviceBusy===x.id?'Kaydediliyor…':enabled?'Açık':'Kapalı'}</span></button>:null;
      const action=isAdmin(user)?<Actions key="a"><button onClick={()=>setEdit(x)}><Pencil size={15}/></button><button onClick={()=>toggle(x)}>{x.is_active?<ToggleRight size={17}/>:<ToggleLeft size={17}/>}</button><button className="danger" onClick={()=>remove(x)}><Trash2 size={15}/></button></Actions>:'—';
      return [x.name,x.code,x.type||'—',x.district||'—',x.contact_person||'—',x.staff_name||'Süper Admin Havuzu',x.estimated_capacity||0,x.login_code||x.code,<Badge key="b" text={x.is_active?'Aktif':'Pasif'} tone={x.is_active?'good':'muted'}/>,...(isAdmin(user)?[serviceCell]:[]),action];
    })}/>
    {edit&&<InstitutionModal boot={boot} item={edit.id?edit:null} preset={edit.erpPreset} close={()=>setEdit(null)} saved={async()=>{setEdit(null);await refreshBoot();list.reload()}}/>}
    {erp&&<ErpInstitutionModal close={()=>setErp(false)} choose={(x:any)=>{setErp(false);setEdit({erpPreset:x})}}/>}
  </>
}
function InstitutionModal({boot,item,preset,close,saved}:{boot:Bootstrap;item:any|null;preset?:any;close:()=>void;saved:()=>void}){const initial=item?{...item,grade_level_ids:item.grade_level_ids||[]}:{province:'İstanbul',is_private:true,grade_level_ids:[],...(preset?{name:preset.name||preset.title||preset.unvan,code:preset.code||preset.customer_code||preset.cari_kod,phone:preset.phone||preset.telefon,email:preset.email,district:preset.district||preset.ilce,erp_external_id:preset.id||preset.erp_external_id}:{} )};const[b,setB]=useState<any>(initial);const toggle=(id:string)=>setB({...b,grade_level_ids:b.grade_level_ids.includes(id)?b.grade_level_ids.filter((x:string)=>x!==id):[...b.grade_level_ids,id]});const save=async()=>{if(!item&&!b.portal_password)throw new Error('Kurum ilk oluşturulurken kurum giriş şifresi zorunludur.');await api(item?`/api/institutions/${item.id}`:'/api/institutions',{method:item?'PATCH':'POST',body:JSON.stringify(b)});saved()};return <Modal title={item?'Kurumu düzenle':'Yeni kurum'} close={close}><FormGrid><Field label="Kurum adı"><input value={b.name||''} onChange={e=>setB({...b,name:e.target.value})}/></Field><Field label="Kurum kodu / giriş kodu"><input value={b.code||''} onChange={e=>setB({...b,code:e.target.value})}/></Field><Field label="Kurum türü"><input placeholder="Kolej, Anadolu Lisesi, Kurs…" value={b.type||''} onChange={e=>setB({...b,type:e.target.value})}/></Field><Field label="İlçe"><input value={b.district||''} onChange={e=>setB({...b,district:e.target.value})}/></Field><Field label="Yetkili"><input value={b.contact_person||''} onChange={e=>setB({...b,contact_person:e.target.value})}/></Field><Field label="Telefon"><input value={b.phone||''} onChange={e=>setB({...b,phone:e.target.value})}/></Field><Field label="Tahmini kapasite"><input type="number" value={b.estimated_capacity||''} onChange={e=>setB({...b,estimated_capacity:e.target.value})}/></Field><Field label="Sorumlu personel"><select value={b.staff_id||''} onChange={e=>setB({...b,staff_id:e.target.value||null})}><option value="">Süper Admin / Yönetim Havuzu</option>{boot.staff.filter(s=>['SUPER_ADMIN','PERSONEL','ADMIN'].includes(s.role)).map(s=><option key={s.id} value={s.id}>{s.full_name} · {roleName(s.role)}</option>)}</select></Field><Field label={item?'Yeni kurum şifresi (değiştirmek için)':'Kurum giriş şifresi'}><input type="password" value={b.portal_password||''} onChange={e=>setB({...b,portal_password:e.target.value})} placeholder={item?'Boş bırakırsanız değişmez':'En az 8 karakter'}/></Field></FormGrid><Field label="Aktif sınıf düzeyleri"><GradeGroupPicker boot={boot} selected={b.grade_level_ids} toggle={toggle}/></Field><ModalActions close={close} save={save}/></Modal>}
function ErpInstitutionModal({close,choose}:{close:()=>void;choose:(x:any)=>void}){const[q,setQ]=useState(''),[items,setItems]=useState<any[]>([]),[msg,setMsg]=useState('');const search=async()=>{const d=await api(`/api/erp/institutions?q=${encodeURIComponent(q)}`);setItems(d.items||[]);setMsg(d.message||(!d.configured?'ERP bağlantısı henüz tanımlı değil. Manuel kurum ekleme kullanılabilir.':''))};return <Modal title="ERP'den cari seç" close={close}><div className="inline-search"><SearchBox value={q} set={setQ}/><button className="btn primary" onClick={search}>Carileri Getir</button></div>{msg&&<div className="info-box">{msg}</div>}<div className="erp-list">{items.map((x:any,i)=><button key={x.id||i} onClick={()=>choose(x)}><b>{x.name||x.title||x.unvan}</b><small>{x.code||x.customer_code||x.cari_kod||'Kod yok'} · {x.district||x.ilce||''}</small></button>)}</div></Modal>}
function GradeGroupPicker({boot,selected,toggle}:{boot:Bootstrap;selected:string[];toggle:(id:string)=>void}){const groups=gradeGroups(boot.grades);return <div className="grade-groups">{Object.entries(groups).map(([name,arr]:any)=><div key={name}><b>{name}</b><div className="chip-wrap">{arr.map((g:any)=><button type="button" key={g.id} className={`chip ${selected.includes(g.id)?'active':''}`} onClick={()=>toggle(g.id)}>{g.name}</button>)}</div></div>)}</div>}
function gradeGroups(grades:any[]){return {İlkokul:grades.filter(g=>['1','2','3','4'].includes(g.code)),Ortaokul:grades.filter(g=>['5','6','7','8'].includes(g.code)),Lise:grades.filter(g=>['9','10','11','TYT','AYT','YDT'].includes(g.code))}}

