function seasonMonthYear(season:any,monthCode:string){const m=Number(monthCode);const start=Number(season?.year_start||new Date().getFullYear());const end=Number(season?.year_end||start+1);return m>=9?start:end}
function calendarCells(year:number,monthCode:string){const m=Number(monthCode);const first=(new Date(year,m-1,1).getDay()+6)%7;const days=new Date(year,m,0).getDate();return Array.from({length:42},(_,i)=>{const d=i-first+1;return d>=1&&d<=days?d:null})}
function eventDate(x:any){return String(x.institution_application_date||x.application_start_date||'').slice(0,10)}
function monthEvents(items:any[],year:number,monthCode:string){const prefix=`${year}-${monthCode}-`;return items.filter(x=>eventDate(x).startsWith(prefix))}
function PlannerCalendarPrint({items,month,season,institution}:{items:any[];month:string;season:any;institution:any}){const ms=month?MONTHS.filter(m=>m.v===month):MONTHS;return <div className="planner-print">{ms.map((m,idx)=>{const year=seasonMonthYear(season,m.v),ev=monthEvents(items,year,m.v),cells=calendarCells(year,m.v);return <section className="planner-page" key={m.v}><div className="planner-head"><div><span>YILDIZ YAYIN</span><h1>{m.n}</h1><p>{year} · {institution?.name||'Deneme Takvimi'}</p></div><div className="planner-year">{year}</div></div><div className="planner-weekdays">{['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar'].map(d=><b key={d}>{d}</b>)}</div><div className="planner-grid">{cells.map((d,i)=>{const dayEv=d?ev.filter(x=>Number(eventDate(x).slice(8,10))===d):[];return <div className={`planner-day ${dayEv.length?'has-exam':''}`} key={i}>{d&&<><strong>{d}</strong><div className="planner-events">{dayEv.slice(0,4).map((x:any)=><span key={x.id}><b>{x.grade_name}</b> {x.publisher_short||x.publisher_name} · {x.exam_name}</span>)}{dayEv.length>4&&<em>+{dayEv.length-4} deneme</em>}</div></>}</div>})}</div><div className="planner-foot"><span>★ Bilginin Yörüngesinde.</span><span>{season?.name||''}</span></div></section>})}</div>}
function AcademicCalendarPrint({items,month,season,institution}:{items:any[];month:string;season:any;institution:any}){const ms=month?MONTHS.filter(m=>m.v===month):MONTHS;return <div className="academic-print"><div className="academic-title"><div className="academic-star">★</div><div><span>YILDIZ YAYIN BASIM DAĞITIM HİZMETLERİ</span><h1>{season?.name||''} DENEME ÇALIŞMA TAKVİMİ</h1><p>{institution?.name||'Kurum Takvimi'} · Eğitimde plan, başarıya yatırım.</p></div></div><div className={`academic-months ${month?'single':''}`}>{ms.map((m,idx)=>{const year=seasonMonthYear(season,m.v),ev=monthEvents(items,year,m.v),cells=calendarCells(year,m.v);return <section className={`academic-month tone-${idx%6}`} key={m.v}><h3>{m.n.toUpperCase()} {year}</h3><div className="academic-week"><b>PT</b><b>SA</b><b>ÇA</b><b>PE</b><b>CU</b><b>CT</b><b>PA</b></div><div className="academic-days">{cells.map((d,i)=>{const n=d?ev.filter(x=>Number(eventDate(x).slice(8,10))===d).length:0;return <span className={n?'exam-day':''} key={i}>{d||''}{n>1&&<small>{n}</small>}</span>})}</div><footer><b>{ev.length}</b> planlı deneme</footer></section>})}</div><div className="academic-info"><div><span className="legend-dot exam"/> Deneme / kurum uygulama günü</div><div><span className="legend-star">★</span> Yıldız Deneme Platformu</div><div>{new Date().toLocaleDateString('tr-TR')}</div></div></div>}
function TemplateModal({close,choose}:{close:()=>void;choose:(x:'standard'|'planner'|'academic')=>void}){return <Modal title="Takvim çıktı şablonunu seçin" close={close}><div className="template-grid"><button onClick={()=>choose('standard')}><div className="template-preview standard"><span>★</span><b>STANDART</b><small>Mevcut kurum takvimi</small></div><b>1. Standart Takvim</b><small>Şu an kullandığınız sade kurumsal çıktı.</small></button><button onClick={()=>choose('planner')}><div className="template-preview planner"><b>Eylül</b><div className="mini-planner-grid">{Array.from({length:28},(_,i)=><i key={i}/>)}</div></div><b>2. Aylık Planlayıcı</b><small>Büyük gün kutuları; gönderdiğiniz sade aylık takvim tarzı.</small></button><button onClick={()=>choose('academic')}><div className="template-preview academic"><strong>2026–2027</strong><div className="mini-year-grid">{Array.from({length:9},(_,i)=><i key={i}/>)}</div></div><b>3. Eğitim Yılı Takvimi</b><small>Renkli aylık kartlarla tek sayfalık sezon görünümü.</small></button></div></Modal>}
function PlanEditModal({x,close,saved}:{x:any;close:()=>void;saved:()=>void}){const[qty,setQty]=useState(String(x.planned_quantity||'')),[date,setDateVal]=useState(x.institution_application_date||'');return <Modal title="Takvim kaydını güncelle" close={close}><Field label="Planlanan adet"><input type="number" value={qty} onChange={e=>setQty(e.target.value)}/></Field><Field label="Kurum uygulama günü"><input type="date" value={date} onChange={e=>setDateVal(e.target.value)}/></Field><ModalActions close={close} save={async()=>{await api(`/api/plans/${x.id}`,{method:'PATCH',body:JSON.stringify({planned_quantity:Number(qty),institution_application_date:date||null})});saved()}}/></Modal>}
function CalendarView({items,month,setDate,setEdit,remove}:{items:any[];month:string;setDate:(x:any,d:string)=>void;setEdit:(x:any)=>void;remove:(x:any)=>void}){if(month){const byGrade=items.reduce((a:any,x:any)=>{(a[x.grade_name]||=[]).push(x);return a},{});return <div className="monthly-general">{Object.entries(byGrade).map(([g,arr]:any)=><section key={g}><h2>{g}</h2><div className="calendar-event-grid">{arr.map((x:any)=><CalendarEvent x={x} key={x.id} setDate={setDate} setEdit={setEdit} remove={remove}/>)}</div></section>)}</div>}const grouped=groupByMonth(items.map(x=>({...x,_date:x.institution_application_date||x.application_start_date})),'_date');return <div className="season-board print-season">{MONTHS.map(m=><div className="month-card" key={m.v}><h3>{m.n}</h3>{(grouped[m.v]||[]).map((x:any)=><CalendarEvent x={x} key={x.id} setDate={setDate} setEdit={setEdit} remove={remove} compact/>)}{!(grouped[m.v]||[]).length&&<small className="muted">—</small>}</div>)}</div>}
function CalendarEvent({x,setDate,setEdit,remove,compact}:{x:any;setDate:(x:any,d:string)=>void;setEdit:(x:any)=>void;remove:(x:any)=>void;compact?:boolean}){return <div className={`calendar-event grade-${x.grade_code}`}><div className="event-date"><b>{fmtShort(x.institution_application_date||x.application_start_date)}</b><span>{x.grade_name}</span></div><div className="event-main"><b>{x.publisher_short} · {x.exam_name}</b><small>{x.subject?`${x.subject} · `:''}{x.institution_application_date?`Kurum günü · Resmî ${fmtShort(x.application_start_date)}–${fmtShort(x.application_end_date)}`:`Resmî ${fmtShort(x.application_start_date)}–${fmtShort(x.application_end_date)}`}</small><em>{x.planned_quantity} adet planlandı</em>{!compact&&<label className="date-edit no-print">Kurum günü <input type="date" value={x.institution_application_date||''} onChange={e=>setDate(x,e.target.value)}/></label>}</div><div className="event-side"><Badge text={x.order_status||statusLabel(x.status)} tone={x.order_id?'good':'warn'}/><Actions><button className="no-print" onClick={()=>setEdit(x)}><Pencil size={14}/></button><button className="danger no-print" onClick={()=>remove(x)}><Trash2 size={14}/></button></Actions></div></div>}
function ProgramView({items,setDate,setEdit,remove}:{items:any[];setDate:(x:any,d:string)=>void;setEdit:(x:any)=>void;remove:(x:any)=>void}){return <DataTable cols={['Tarih','Sınıf','Yayınevi','Sınav','Adet','Sipariş','Kurum Günü','İşlem']} rows={items.map(x=>[fmtDate(x.institution_application_date||x.application_start_date),x.grade_name,x.publisher_name,x.exam_name,x.planned_quantity,x.order_status||statusLabel(x.status),<input key="d" className="date-inline no-print" type="date" value={x.institution_application_date||''} onChange={e=>setDate(x,e.target.value)}/>,<Actions key="a"><button onClick={()=>setEdit(x)}><Pencil size={14}/></button><button className="danger" onClick={()=>remove(x)}><Trash2 size={14}/></button></Actions>])}/>} 
const statusLabel=(s:string)=>({PLANLANDI:'Planlandı',SIPARIS_BEKLIYOR:'Sipariş Bekliyor',SIPARIS_VERILDI:'Sipariş Verildi',ONAYLANDI:'Onaylandı',TEDARIK:'Tedarik',TESLIM_EDILDI:'Teslim Edildi'} as any)[s]||s;

// SALES
function Sales({boot,sub,user}:{boot:Bootstrap;sub:string;user:User}){if(sub==='Kuruma Sipariş Gir')return <AdminInstitutionOrderEntry boot={boot} user={user}/>;if(sub==='Siparişler')return <Orders boot={boot} user={user}/>;if(sub==='Sipariş Bekleyenler')return <PendingOrders boot={boot} user={user}/>;return <Opportunities/>}
function AdminInstitutionOrderEntry({boot,user}:{boot:Bootstrap;user:User}){if(!isAdmin(user)||!permitted(boot,'ORDERS_CREATE'))return <Empty text="Bu bölüm yalnız yetkili yönetici kullanıcılarına açıktır."/>;const[inst,setInst]=useState(boot.institutions[0]?.id||''),[season,setSeason]=useState(boot.seasons.find(s=>s.is_active)?.id||''),[grade,setGrade]=useState(''),[publisher,setPublisher]=useState(''),[month,setMonth]=useState(''),[q,setQ]=useState(''),[selected,setSelected]=useState<Set<string>>(new Set()),[qty,setQty]=useState<Record<string,string>>({}),[msg,setMsg]=useState('');const exams=useAsync(()=>api(`/api/exams?season_id=${season}&active=1${grade?`&grade_level_id=${grade}`:''}${publisher?`&publisher_id=${publisher}`:''}${month?`&month=${month}`:''}${q?`&q=${encodeURIComponent(q)}`:''}`),[season,grade,publisher,month,q]);const items=(exams.data as any)?.items||[];const toggle=(id:string)=>setSelected(v=>{const n=new Set(v);n.has(id)?n.delete(id):n.add(id);return n});const saveOne=async(x:any)=>{const n=Number(qty[x.id]||0);if(n<=0)return alert('Adet girin.');await api('/api/orders',{method:'POST',body:JSON.stringify({institution_id:inst,exam_id:x.id,quantity:n})});setMsg(`${x.name}: ${n} adet sipariş kaydedildi.`);setQty({...qty,[x.id]:''});setSelected(v=>{const n=new Set(v);n.delete(x.id);return n})};const saveBulk=async()=>{const rows=[...selected].map(id=>({exam_id:id,quantity:Number(qty[id]||0)}));if(!inst||!rows.length)return;const invalid=rows.find(x=>x.quantity<=0);if(invalid)return alert('Seçili her deneme için adet girin.');const d=await api('/api/orders/bulk',{method:'POST',body:JSON.stringify({institution_id:inst,items:rows})});setMsg(`${d.created||0} sipariş oluşturuldu${d.errors?.length?`, ${d.errors.length} kayıt atlandı`:''}.`);setSelected(new Set());setQty({})};return <><div className="admin-order-hero"><div><span className="pill gold"><ShoppingCart size={14}/> Yönetici Sipariş Girişi</span><h2>Kuruma Sipariş Gir</h2><p>Kurum seçin; sipariş geldikçe tek tek veya birden fazla denemeyi toplu kaydedin.</p></div><div className="admin-order-inst"><label>Kurum</label><select value={inst} onChange={e=>setInst(e.target.value)}>{boot.institutions.filter(i=>i.is_active!==0).map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></div></div><Toolbar><select value={season} onChange={e=>setSeason(e.target.value)}>{boot.seasons.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><select value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{boot.grades.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select><select value={publisher} onChange={e=>setPublisher(e.target.value)}><option value="">Tüm yayınevleri</option>{boot.publishers.map(p=><option key={p.id} value={p.id}>{p.short_name||p.name}</option>)}</select><select value={month} onChange={e=>setMonth(e.target.value)}><option value="">Tüm aylar</option>{MONTHS.map(m=><option value={m.v} key={m.v}>{m.n}</option>)}</select><SearchBox value={q} set={setQ}/><div className="spacer"/><button className="btn primary" disabled={!selected.size} onClick={saveBulk}>{selected.size} Seçileni Toplu Kaydet</button></Toolbar>{msg&&<div className="success-box"><CheckCircle2 size={18}/>{msg}</div>}<DataTable cols={['Seç','Sınıf','Yayınevi','Deneme','Son Sipariş','Uygulama','Adet','']} rows={items.map((x:any)=>[<input key="c" type="checkbox" checked={selected.has(x.id)} onChange={()=>toggle(x.id)}/>,x.grade_name,x.publisher_short||x.publisher_name,x.name,fmtDate(x.last_order_date),`${fmtShort(x.application_start_date)}–${fmtShort(x.application_end_date)}`,<input key="q" className="qty-inline" type="number" min="1" value={qty[x.id]||''} onChange={e=>setQty({...qty,[x.id]:e.target.value})}/>,<button key="b" className="btn tiny" onClick={()=>saveOne(x)}>Sipariş Gir</button>])}/></>}

function Opportunities(){const q=useAsync(()=>api('/api/opportunities'),[]);const items=(q.data as any)?.items||[];const update=async(x:any,status:string)=>{await api(`/api/opportunities/${x.id}`,{method:'PATCH',body:JSON.stringify({status})});q.reload()};return <><Toolbar><button className="btn" onClick={async()=>{await api('/api/opportunities/generate',{method:'POST'});q.reload()}}><RefreshCw size={16}/> Fırsatları Güncelle</button></Toolbar><div className="opportunity-list">{items.map((x:any)=><div className="opp-card" key={x.id}><div className={`priority ${String(x.priority||'MEDIUM').toLowerCase()}`}>{x.priority}</div><div className="opp-main"><b>{x.institution_name}</b><span>{x.grade_name} · {x.publisher_name} · {x.exam_name}</span><small>Sorumlu: {x.staff_name||'Süper Admin'} · Son sipariş {fmtDate(x.last_order_date)}</small></div><select value={x.status} onChange={e=>update(x,e.target.value)}><option>ARANACAK</option><option>GORUSULDU</option><option>TEKLIF_VERILDI</option><option>KARAR_BEKLENIYOR</option><option>SIPARIS_VERDI</option><option>ILGILENMIYOR</option><option>BASKA_YAYINEVI_ALDI</option><option>KATILMAYACAK</option><option>ULASILAMADI</option></select></div>)}</div>{!items.length&&<Empty text="Satış fırsatı yok."/>}</>}
function PendingOrders({boot,user}:{boot:Bootstrap;user:User}){const q=useAsync(()=>api('/api/order-pending'),[]),[order,setOrder]=useState<any|null>(null);const items=(q.data as any)?.items||[];return <><div className="kpi-grid compact"><Kpi icon={Clock3} label="Sipariş Bekleyen" value={items.length} sub={`${items.reduce((s:number,x:any)=>s+Number(x.planned_quantity||0),0)} planlanan adet`}/></div><DataTable cols={['Kurum','Sınıf','Yayınevi','Sınav','Planlanan Adet','Son Sipariş','']} rows={items.map((x:any)=>[x.institution_name,x.grade_name,x.publisher_short,x.exam_name,x.planned_quantity,fmtDate(x.last_order_date),<button key="a" className="btn tiny primary" onClick={()=>setOrder(x)}>Siparişe Çevir</button>])}/>{order&&<OrderConfirmModal x={order} close={()=>setOrder(null)} saved={()=>{setOrder(null);q.reload()}}/>}</>}
function OrderConfirmModal({x,close,saved}:{x:any;close:()=>void;saved:()=>void}){const[qty,setQty]=useState(String(x.planned_quantity||'')),[price,setPrice]=useState(String(Number(x.default_sale_price||0)/100));return <Modal title="Siparişi onayla" close={close}><div className="summary-box"><b>{x.institution_name}</b><span>{x.grade_name} · {x.publisher_name} · {x.exam_name}</span></div><FormGrid><Field label="Adet"><input type="number" value={qty} onChange={e=>setQty(e.target.value)}/></Field><Field label="Birim fiyat (TL)"><input type="number" value={price} onChange={e=>setPrice(e.target.value)}/></Field></FormGrid><ModalActions close={close} save={async()=>{await api('/api/orders',{method:'POST',body:JSON.stringify({institution_id:x.institution_id,exam_id:x.exam_id,quantity:Number(qty),unit_price:Math.round(Number(price)*100)})});saved()}}/></Modal>}
function Orders({boot,user}:{boot:Bootstrap;user:User}){const q=useAsync(()=>api('/api/orders'),[]),[edit,setEdit]=useState<any|null>(null),[modal,setModal]=useState(false);const items=(q.data as any)?.items||[],canCreate=permitted(boot,'ORDERS_CREATE'),canEdit=permitted(boot,'ORDERS_EDIT'),canDelete=permitted(boot,'ORDERS_DELETE');const patch=async(x:any,b:any)=>{await api(`/api/orders/${x.id}`,{method:'PATCH',body:JSON.stringify(b)});q.reload()};const remove=async(x:any)=>{if(!confirm('Bu sipariş silinsin mi? İşlem geçmişi denetim kaydında korunacaktır.'))return;await api(`/api/orders/${x.id}`,{method:'DELETE'});q.reload()};return <><Toolbar><div className="spacer"/>{canCreate&&<button className="btn primary" onClick={()=>setModal(true)}><Plus size={16}/> Sipariş Gir</button>}</Toolbar><DataTable cols={['Tarih','Kurum','Sınıf','Yayınevi','Sınav','Adet','Toplam','Durum','Gönderildi','Teslim','Uygulandı','İşlem']} rows={items.map((x:any)=>[new Date(x.created_at).toLocaleDateString('tr-TR'),x.institution_name,x.grade_name,x.publisher_name,x.exam_name,x.quantity,fmtMoney(x.total_price),<Badge key="s" text={x.status} tone={x.status==='TESLIM_EDILDI'?'good':'info'}/>,<OpCheck key="sent" checked={!!x.sent_to_institution_at} label="Gönderildi" onChange={v=>patch(x,{sent_to_institution:v})}/>,<OpCheck key="del" checked={!!x.delivered_at||x.status==='TESLIM_EDILDI'} label="Teslim" onChange={v=>patch(x,{delivered:v})}/>,<OpCheck key="app" checked={!!x.exam_applied_at} label="Uygulandı" onChange={v=>patch(x,{exam_applied:v})}/>,<Actions key="a">{canEdit&&<button onClick={()=>setEdit(x)} title="Düzenle"><Pencil size={15}/></button>}{canDelete&&<button className="danger" onClick={()=>remove(x)} title="Sil"><Trash2 size={15}/></button>}</Actions>])}/>{modal&&<OrderModal boot={boot} user={user} close={()=>setModal(false)} saved={()=>{setModal(false);q.reload()}}/>}{edit&&<OrderEditModal x={edit} close={()=>setEdit(null)} saved={()=>{setEdit(null);q.reload()}}/>}</>}
function OpCheck({checked,label,onChange}:{checked:boolean;label:string;onChange:(v:boolean)=>void}){return <label className={`op-check ${checked?'done':''}`} title={label}><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/><span>{checked?'✓':'○'}</span></label>}
function OrderModal({boot,user,close,saved}:{boot:Bootstrap;user:User;close:()=>void;saved:()=>void}){const[inst,setInst]=useState(user.role==='KURUM'?user.institution_id||'':boot.institutions[0]?.id||''),[exam,setExam]=useState(''),[qty,setQty]=useState(''),[price,setPrice]=useState('');const exams=useAsync(()=>api(`/api/exams?season_id=${boot.seasons.find(s=>s.is_active)?.id||''}&active=1`),[]);const availableInstitutions=user.role==='PERSONEL'?boot.institutions.filter(i=>i.staff_id===user.id):boot.institutions;return <Modal title="Sipariş oluştur ve onayla" close={close}><FormGrid>{user.role!=='KURUM'&&<Field label="Kurum"><select value={inst} onChange={e=>setInst(e.target.value)}>{availableInstitutions.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></Field>}<Field label="Sınav"><select value={exam} onChange={e=>setExam(e.target.value)}><option value="">Seçiniz</option>{((exams.data as any)?.items||[]).map((x:any)=><option key={x.id} value={x.id}>{x.grade_name} · {x.publisher_short} · {x.name}</option>)}</select></Field><Field label="Adet"><input type="number" value={qty} onChange={e=>setQty(e.target.value)}/></Field><Field label="Birim fiyat (TL, boşsa varsayılan)"><input type="number" value={price} onChange={e=>setPrice(e.target.value)}/></Field></FormGrid><ModalActions close={close} save={async()=>{await api('/api/orders',{method:'POST',body:JSON.stringify({institution_id:inst,exam_id:exam,quantity:Number(qty),unit_price:price?Math.round(Number(price)*100):undefined})});saved()}}/></Modal>}
function OrderEditModal({x,close,saved}:{x:any;close:()=>void;saved:()=>void}){const[qty,setQty]=useState(String(x.quantity)),[price,setPrice]=useState(String(Number(x.unit_price||0)/100)),[status,setStatus]=useState(x.status),[notes,setNotes]=useState(x.notes||'');return <Modal title="Siparişi düzenle" close={close}><FormGrid><Field label="Adet"><input type="number" value={qty} onChange={e=>setQty(e.target.value)}/></Field><Field label="Birim fiyat (TL)"><input type="number" value={price} onChange={e=>setPrice(e.target.value)}/></Field><Field label="Durum"><select value={status} onChange={e=>setStatus(e.target.value)}><option>ONAYLANDI</option><option>SIPARIS_LISTESINDE</option><option>B2B_SIPARISI_VERILDI</option><option>URUN_GELDI</option><option>TESLIM_EDILDI</option><option>IPTAL</option></select></Field><Field label="Not"><input value={notes} onChange={e=>setNotes(e.target.value)}/></Field></FormGrid><ModalActions close={close} save={async()=>{await api(`/api/orders/${x.id}`,{method:'PATCH',body:JSON.stringify({quantity:Number(qty),unit_price:Math.round(Number(price)*100),status,notes})});saved()}}/></Modal>}

// PUBLISHERS + ORDER LISTS
function Publishers({boot,sub,user,refreshBoot}:{boot:Bootstrap;sub:string;user:User;refreshBoot:()=>Promise<void>}){return sub==='Sipariş Listeleri'?<OrderLists user={user} boot={boot}/>:<PublisherList boot={boot} user={user} refreshBoot={refreshBoot}/>}
function PublisherList({boot,user,refreshBoot}:{boot:Bootstrap;user:User;refreshBoot:()=>Promise<void>}){const q=useAsync(()=>api('/api/publishers'),[]),[edit,setEdit]=useState<any|null>(null),[selected,setSelected]=useState<any|null>(null);const items=(q.data as any)?.items||boot.publishers;const remove=async(x:any)=>{if(!confirm(`${x.name} silinsin/pasife alınsın mı?`))return;await api(`/api/publishers/${x.id}`,{method:'DELETE'});q.reload();refreshBoot()};const toggle=async(x:any)=>{await api(`/api/publishers/${x.id}`,{method:'PATCH',body:JSON.stringify({is_active:!x.is_active})});q.reload();refreshBoot()};return <><div className="card-grid">{items.map((x:any)=><div className={`publisher-card clickable ${!x.is_active?'inactive':''}`} key={x.id} onClick={()=>setSelected(x)}><div className="publisher-mark">{x.logo_url?<img src={x.logo_url}/>:x.short_name?.slice(0,3).toUpperCase()}</div><div className="publisher-content"><h3>{x.name}</h3><p>{x.sales_representative||x.contact_person||'Yetkili tanımlanmadı'}</p><small>{x.phone||'—'} · Denemeleri görmek için tıklayın</small></div>{isAdmin(user)&&<Actions><button onClick={e=>{e.stopPropagation();setEdit(x)}}><Pencil size={15}/></button><button onClick={e=>{e.stopPropagation();toggle(x)}}>{x.is_active?<ToggleRight size={17}/>:<ToggleLeft size={17}/>}</button><button className="danger" onClick={e=>{e.stopPropagation();remove(x)}}><Trash2 size={15}/></button></Actions>}</div>)}</div>{isAdmin(user)&&<button className="fab" onClick={()=>setEdit({})}><Plus/></button>}{selected&&<PublisherExamBrowser boot={boot} publisher={selected} close={()=>setSelected(null)}/>} {edit&&<PublisherModal item={edit.id?edit:null} close={()=>setEdit(null)} saved={async()=>{setEdit(null);await refreshBoot();q.reload()}}/>}</>}
function PublisherExamBrowser({boot,publisher,close}:{boot:Bootstrap;publisher:any;close:()=>void}){const[season,setSeason]=useState(boot.seasons.find(s=>s.is_active)?.id||''),[grade,setGrade]=useState(''),[active,setActive]=useState('1'),[month,setMonth]=useState(''),[q,setQ]=useState('');const list=useAsync(()=>api(`/api/exams?publisher_id=${publisher.id}&season_id=${season}${grade?`&grade_level_id=${grade}`:''}${active?`&active=${active}`:''}${month?`&month=${month}`:''}${q?`&q=${encodeURIComponent(q)}`:''}`),[publisher.id,season,grade,active,month,q]);const items=(list.data as any)?.items||[];return <Modal title={`${publisher.name} · Deneme Kataloğu`} close={close}><Toolbar><select value={season} onChange={e=>setSeason(e.target.value)}>{boot.seasons.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><select value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{boot.grades.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select><select value={active} onChange={e=>setActive(e.target.value)}><option value="1">Aktif</option><option value="0">Pasif</option><option value="">Tümü</option></select><select value={month} onChange={e=>setMonth(e.target.value)}><option value="">Tüm aylar</option>{MONTHS.map(m=><option key={m.v} value={m.v}>{m.n}</option>)}</select><SearchBox value={q} set={setQ}/></Toolbar>{list.loading?<Loading/>:<DataTable cols={['Tarih','Sınıf','Tür','Zorluk','Deneme','Kod','Son Sipariş','Uygulama']} rows={items.map((x:any)=>[fmtDate(x.application_start_date),x.grade_name,x.exam_type||'DENEME',x.difficulty_level||'—',x.name,x.code,fmtDate(x.last_order_date),`${fmtShort(x.application_start_date)}–${fmtShort(x.application_end_date)}`])}/>} {!items.length&&!list.loading&&<Empty text="Bu filtrelerde tanımlı deneme yok."/>}</Modal>}
function PublisherModal({item,close,saved}:{item:any|null;close:()=>void;saved:()=>void}){const[b,setB]=useState<any>(item?{...item}:{minimum_order:1,delivery_days:14,is_active:1});const logo=async(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(!f)return;if(f.size>500*1024)return alert('Logo en fazla 500 KB olmalı.');const reader=new FileReader();reader.onload=()=>setB({...b,logo_url:String(reader.result)});reader.readAsDataURL(f)};return <Modal title={item?'Yayınevini düzenle':'Yayınevi ekle'} close={close}><FormGrid><Field label="Yayınevi"><input value={b.name||''} onChange={e=>setB({...b,name:e.target.value})}/></Field><Field label="Kısa ad"><input value={b.short_name||''} onChange={e=>setB({...b,short_name:e.target.value})}/></Field><Field label="Satış temsilcisi"><input value={b.sales_representative||''} onChange={e=>setB({...b,sales_representative:e.target.value})}/></Field><Field label="Telefon"><input value={b.phone||''} onChange={e=>setB({...b,phone:e.target.value})}/></Field></FormGrid><Field label="Yayınevi logosu"><div className="logo-upload">{b.logo_url?<img src={b.logo_url}/>:<ImageIcon/>}<label className="btn">Logo seç<input hidden type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" onChange={logo}/></label>{b.logo_url&&<button className="btn" onClick={()=>setB({...b,logo_url:null})}>Kaldır</button>}</div></Field><ModalActions close={close} save={async()=>{await api(item?`/api/publishers/${item.id}`:'/api/publishers',{method:item?'PATCH':'POST',body:JSON.stringify(b)});saved()}}/></Modal>}
function OrderLists({user,boot}:{user:User;boot:Bootstrap}){const preview=useAsync(()=>api('/api/order-lists/preview'),[]),lists=useAsync(()=>api('/api/publisher-orders'),[]),[edit,setEdit]=useState<any|null>(null);if(!['SUPER_ADMIN','ADMIN','OPERASYON'].includes(user.role))return <Empty text="Bu bölüm için yetkiniz yok."/>;const p=(preview.data as any)?.items||[],l=(lists.data as any)?.items||[];const urgent=p.filter((x:any)=>{if(!x.last_order_date)return false;return (new Date(`${x.last_order_date}T12:00:00`).getTime()-Date.now())/86400000<=7});const byPublisher=p.reduce((a:any,x:any)=>{const k=x.publisher_name;(a[k]||={publisher_name:k,total:0,exams:0}).total+=Number(x.total_quantity||0);a[k].exams++;return a},{});const exportList=async(x:any)=>{const XLSX=await import('xlsx');const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet([{Yayınevi:x.publisher_name,Sınav:x.exam_name,Sınıf:x.grade_name,'Toplam Adet':x.total_quantity,'Kurum Sayısı':x.institution_count,'Son Sipariş':x.last_order_date}]),'Sipariş Listesi');XLSX.writeFile(wb,`${x.publisher_short||'Yayinevi'}-${x.exam_code}-Siparis-Listesi.xlsx`)};return <><div className="kpi-grid compact"><Kpi icon={Clock3} label="Acil Sipariş" value={urgent.length} sub="7 gün içinde son sipariş"/><Kpi icon={ClipboardList} label="Liste Bekleyen" value={p.length} sub={`${p.reduce((s:number,x:any)=>s+Number(x.total_quantity||0),0)} adet`}/><Kpi icon={PackageCheck} label="Oluşan Listeler" value={l.length} sub={`${l.filter((x:any)=>x.status==='B2B_SIPARISI_VERILDI').length} B2B'ye verildi`}/></div><h3 className="section-title">Yayınevleri · hızlı kontrol</h3><div className="card-grid compact-cards">{Object.values(byPublisher).map((x:any)=><div className="publisher-summary" key={x.publisher_name}><Warehouse/><div><b>{x.publisher_name}</b><span>{x.exams} sınav · {x.total} adet liste bekliyor</span></div></div>)}</div><Panel title="Yaklaşan / acil sipariş listeleri" icon={AlertTriangle}>{p.length?<DataTable cols={['Son Sipariş','Yayınevi','Sınıf','Sınav','Kurum','Toplam','İşlem']} rows={p.map((x:any)=>[fmtDate(x.last_order_date),x.publisher_name,x.grade_name,x.exam_name,x.institution_count,x.total_quantity,<Actions key="a"><button title="Excel" onClick={()=>exportList(x)}><FileSpreadsheet size={15}/></button><button className="btnlike" onClick={async()=>{await api('/api/publisher-orders',{method:'POST',body:JSON.stringify({exam_id:x.exam_id})});preview.reload();lists.reload()}}>Sipariş Listesi Oluştur</button></Actions>])}/>:<Empty text="Liste oluşturulacak onaylı sipariş yok."/>}</Panel><h3 className="section-title">Oluşturulan sipariş listeleri</h3><DataTable cols={['Yayınevi','Sınav','Sınıf','Toplam','Gelen','Eksik','B2B Durumu','İşlem']} rows={l.map((x:any)=>[x.publisher_name,x.exam_name,x.grade_name,x.total_quantity,x.received_quantity||0,x.missing_quantity||0,<Badge key="b" text={x.status} tone={x.status==='B2B_SIPARISI_VERILDI'?'good':x.status==='KISMI_GELDI'?'warn':'info'}/>,<button key="a" className="btn tiny" onClick={()=>setEdit(x)}>Detay / B2B Onayı</button>])}/>{edit&&<B2BModal x={edit} close={()=>setEdit(null)} saved={()=>{setEdit(null);lists.reload();preview.reload()}}/>}</>}
function B2BModal({x,close,saved}:{x:any;close:()=>void;saved:()=>void}){const[number,setNumber]=useState(x.order_number||''),[notes,setNotes]=useState(x.b2b_notes||'');return <Modal title="Yayınevi B2B sipariş onayı" close={close}><div className="summary-box"><b>{x.publisher_name}</b><span>{x.exam_name} · {x.total_quantity} adet</span></div><p className="muted">Siparişi yayınevinin kendi B2B sisteminden verdikten sonra burada onaylayın.</p><Field label="B2B sipariş numarası"><input value={number} onChange={e=>setNumber(e.target.value)}/></Field><Field label="Not"><textarea value={notes} onChange={e=>setNotes(e.target.value)}/></Field><ModalActions close={close} save={async()=>{await api(`/api/publisher-orders/${x.id}`,{method:'PATCH',body:JSON.stringify({status:'B2B_SIPARISI_VERILDI',order_number:number,b2b_notes:notes})});saved()}}/></Modal>}

// OPERATIONS
function InstitutionOperations(){const q=useAsync(()=>api('/api/orders'),[]);if(q.loading)return <Loading/>;if(q.error)return <ErrorState text={q.error} retry={q.reload}/>;const all=((q.data as any)?.items||[]).filter((x:any)=>x.status!=='IPTAL');const arrived=all.filter((x:any)=>x.delivered_at);const coming=all.filter((x:any)=>!x.delivered_at);const status=(x:any)=>x.delivered_at?'Geldi':x.sent_to_institution_at?'Yolda':x.status==='URUN_GELDI'?'Gönderime Hazırlanıyor':'Tedarik / Hazırlık';return <><div className="institution-ops-head"><div><h2>Deneme Operasyonum</h2><p>Yalnız kurumunuzun sipariş verdiği denemeler gösterilir.</p></div><div className="ops-counts"><span><b>{coming.length}</b> gelecek</span><span><b>{arrived.length}</b> gelen</span></div></div><div className="institution-ops-grid"><Panel title="Gelecek Denemeler" icon={Truck}>{coming.length?<DataTable cols={['Sınıf','Yayınevi','Deneme','Adet','Tahmini Sevk','Uygulama','Durum']} rows={coming.map((x:any)=>[x.grade_name,x.publisher_name,x.exam_name,x.quantity,fmtDate(x.estimated_ship_date),`${fmtShort(x.application_start_date)}–${fmtShort(x.application_end_date)}`,<Badge key="s" text={status(x)} tone={x.sent_to_institution_at?'info':'warn'}/>])}/>:<Empty text="Gelecek deneme bulunmuyor."/>}</Panel><Panel title="Gelen Denemeler" icon={PackageCheck}>{arrived.length?<DataTable cols={['Sınıf','Yayınevi','Deneme','Adet','Teslim Tarihi','Uygulama Durumu']} rows={arrived.map((x:any)=>[x.grade_name,x.publisher_name,x.exam_name,x.quantity,fmtDate(String(x.delivered_at).slice(0,10)),x.exam_applied_at?<Badge key="a" text="Uygulandı" tone="good"/>:<Badge key="a" text="Uygulama Bekliyor" tone="info"/>])}/>:<Empty text="Henüz kuruma ulaşmış deneme bulunmuyor."/>}</Panel></div></>}


function Operations({boot,sub}:{boot:Bootstrap;sub:string}){const[tab,setTab]=useState<'supply'|'delivery'>(sub==='Teslimatlar'?'delivery':'supply');useEffect(()=>setTab(sub==='Teslimatlar'?'delivery':'supply'),[sub]);return <><div className="segmented page-segment"><button className={tab==='supply'?'active':''} onClick={()=>setTab('supply')}>Tedarik / Gelen Ürün</button><button className={tab==='delivery'?'active':''} onClick={()=>setTab('delivery')}>Teslimatlar</button></div>{tab==='supply'?<Procurement/>:<Deliveries/>}</>}
function Procurement(){const q=useAsync(()=>api('/api/publisher-orders'),[]),[receipt,setReceipt]=useState<any|null>(null);return <><DataTable cols={['Yayınevi','Sınav','Sipariş','Gelen','Eksik','Durum','']} rows={((q.data as any)?.items||[]).map((x:any)=>[x.publisher_name,x.exam_name,x.total_quantity,x.received_quantity||0,x.missing_quantity||0,<Badge key="b" text={x.status} tone={x.status==='TAM_GELDI'?'good':x.status==='KISMI_GELDI'?'warn':'info'}/>,<button key="a" className="btn tiny" onClick={()=>setReceipt(x)}>Ürün Kabul</button>])}/>{receipt&&<ReceiptModal x={receipt} close={()=>setReceipt(null)} saved={()=>{setReceipt(null);q.reload()}}/>}</>}
function ReceiptModal({x,close,saved}:{x:any;close:()=>void;saved:()=>void}){const[qty,setQty]=useState(''),[notes,setNotes]=useState('');return <Modal title={`${x.exam_name} · Ürün kabul`} close={close}><div className="summary-box"><b>Sipariş: {x.total_quantity} adet</b><span>Gelen: {x.received_quantity||0}</span><span>Eksik: {x.missing_quantity??x.total_quantity}</span></div><Field label="Bu sevkiyatta gelen adet"><input type="number" value={qty} onChange={e=>setQty(e.target.value)}/></Field><Field label="Not"><textarea value={notes} onChange={e=>setNotes(e.target.value)}/></Field><ModalActions close={close} save={async()=>{await api('/api/goods-receipts',{method:'POST',body:JSON.stringify({publisher_order_id:x.id,received_quantity:Number(qty),notes})});saved()}}/></Modal>}
function Deliveries(){const q=useAsync(()=>api('/api/deliveries'),[]),orders=useAsync(()=>api('/api/orders'),[]),[modal,setModal]=useState(false);const setStatus=async(x:any,status:string)=>{await api(`/api/deliveries/${x.id}`,{method:'PATCH',body:JSON.stringify({status})});q.reload()};return <><Toolbar><div className="spacer"/><button className="btn primary" onClick={()=>setModal(true)}><Plus size={16}/> Teslimat Oluştur</button></Toolbar><DataTable cols={['Kurum','Sınıf','Sınav','Adet','Yöntem','Kargo','Takip','Durum']} rows={((q.data as any)?.items||[]).map((x:any)=>[x.institution_name,x.grade_name,x.exam_name,x.quantity,x.delivery_method||'—',x.carrier||'—',x.tracking_number||'—',<select key="s" value={x.status} onChange={e=>setStatus(x,e.target.value)}><option>HAZIRLANIYOR</option><option>HAZIR</option><option>SEVK_EDILDI</option><option>PERSONEL_TESLIM</option><option>KARGO</option><option>KURUMDAN_TESLIM</option><option>TESLIM_EDILDI</option></select>])}/>{modal&&<DeliveryModal orders={(orders.data as any)?.items||[]} close={()=>setModal(false)} saved={()=>{setModal(false);q.reload()}}/>}</>}
function DeliveryModal({orders,close,saved}:{orders:any[];close:()=>void;saved:()=>void}){const[b,setB]=useState<any>({delivery_method:'KARGO',status:'HAZIRLANIYOR'});return <Modal title="Teslimat oluştur" close={close}><FormGrid><Field label="Sipariş"><select value={b.order_id||''} onChange={e=>{const o=orders.find(x=>x.id===e.target.value);setB({...b,order_id:e.target.value,quantity:o?.quantity||''})}}><option value="">Seçiniz</option>{orders.filter(x=>x.status!=='IPTAL').map(x=><option key={x.id} value={x.id}>{x.institution_name} · {x.exam_name} · {x.quantity}</option>)}</select></Field><Field label="Adet"><input type="number" value={b.quantity||''} onChange={e=>setB({...b,quantity:e.target.value})}/></Field><Field label="Teslim yöntemi"><select value={b.delivery_method} onChange={e=>setB({...b,delivery_method:e.target.value})}><option>KARGO</option><option>PERSONEL_TESLIM</option><option>KURUMDAN_TESLIM</option></select></Field><Field label="Kargo / taşıyıcı"><input value={b.carrier||''} onChange={e=>setB({...b,carrier:e.target.value})}/></Field><Field label="Takip no"><input value={b.tracking_number||''} onChange={e=>setB({...b,tracking_number:e.target.value})}/></Field></FormGrid><ModalActions close={close} save={async()=>{await api('/api/deliveries',{method:'POST',body:JSON.stringify({...b,quantity:Number(b.quantity)})});saved()}}/></Modal>}

function Reports(){const q=useAsync(()=>api('/api/reports/summary'),[]);if(q.loading)return <Loading/>;const d:any=q.data||{};return <><div className="kpi-grid"><Kpi icon={CalendarRange} label="Planlanan" value={d.planned?.total||0} sub="Kurum sezon planları"/><Kpi icon={CheckCircle2} label="Siparişe Dönüşen" value={d.planned?.converted||0} sub={`${d.planned?.total?Math.round((d.planned.converted/d.planned.total)*100):0}% dönüşüm`}/><Kpi icon={Send} label="Kuruma Gönderilen" value={d.operations?.sent||0} sub={`${d.operations?.delivered||0} teslim edildi`}/><Kpi icon={CheckCircle2} label="Sınav Uygulandı" value={d.operations?.applied||0} sub="Operasyon onayı"/></div><div className="grid-2"><Panel title="Yayınevi satışları" icon={BookOpen}><MiniReport rows={d.by_publisher||[]}/></Panel><Panel title="Sınıf düzeyi satışları" icon={Users}><MiniReport rows={d.by_grade||[]}/></Panel></div><Panel title="Kaçan satış nedenleri" icon={AlertTriangle}><DataTable cols={['Neden','Adet']} rows={(d.losses||[]).map((x:any)=>[x.label,x.count])}/></Panel></>}
function MiniReport({rows}:{rows:any[]}){const max=Math.max(...rows.map(r=>Number(r.revenue||0)),1);return <div className="mini-report">{rows.map((r:any)=><div key={r.label}><div className="mini-label"><b>{r.label}</b><span>{r.quantity||0} adet · {fmtMoney(r.revenue)}</span></div><div className="bar"><i style={{width:`${Math.max(3,Number(r.revenue||0)/max*100)}%`}}/></div></div>)}{!rows.length&&<Empty text="Henüz satış verisi yok."/>}</div>}

function Management({boot,sub,refreshBoot}:{boot:Bootstrap;sub:string;refreshBoot:()=>Promise<void>}){if(sub==='Sezonlar')return <Seasons boot={boot} refreshBoot={refreshBoot}/>;if(sub==='Kullanıcılar')return <UsersAdmin boot={boot}/>;if(sub==='Yetkiler')return <PermissionsAdmin boot={boot}/>;if(sub==='Görevler')return <TasksAdmin boot={boot}/>;if(sub==='Ayarlar')return <NotificationSettings/>;if(sub==='Entegrasyonlar')return <Integration/>;return <Panel title="Sistem ayarları" icon={Settings}><p className="muted">Kapsam: sınav takvimi, kurum planlama, satış, sipariş listeleri, tedarik, teslimat, dijital cevap anahtarları ve ticari raporlama.</p></Panel>}
function UsersAdmin({boot}:{boot:Bootstrap}){const q=useAsync(()=>api('/api/users'),[]),[edit,setEdit]=useState<any|null>(null),[passwordUser,setPasswordUser]=useState<any|null>(null);const toggle=async(x:any)=>{await api(`/api/users/${x.id}`,{method:'PATCH',body:JSON.stringify({status:x.status==='ACTIVE'?'PASSIVE':'ACTIVE'})});q.reload()};const remove=async(x:any)=>{if(!confirm(`${x.full_name} kullanıcısı silinsin mi?`))return;await api(`/api/users/${x.id}`,{method:'DELETE'});q.reload()};return <><Toolbar><div className="spacer"/><button className="btn primary" onClick={()=>setEdit({})}><Plus size={16}/> Kullanıcı Ekle</button></Toolbar><DataTable cols={['Ad Soyad','E-posta / Kod','Rol','Kurum','Durum','İşlem']} rows={((q.data as any)?.items||[]).map((x:any)=>{const superAdmin=x.role==='SUPER_ADMIN';return [x.full_name,x.login_code||x.email,roleName(x.role),boot.institutions.find(i=>i.id===x.institution_id)?.name||'—',<Badge key="s" text={x.status==='ACTIVE'?'Aktif':'Pasif'} tone={x.status==='ACTIVE'?'good':'muted'}/>,superAdmin?<Actions key="a"><span className="protected-user"><KeyRound size={14}/> Dokunulmaz</span>{boot.user.id===x.id&&<button onClick={()=>setPasswordUser(x)} title="Şifre değiştir"><KeyRound size={15}/></button>}</Actions>:<Actions key="a"><button onClick={()=>setEdit(x)} title="Düzenle"><Pencil size={15}/></button>{boot.user.id!==x.id&&<button onClick={()=>toggle(x)} title={x.status==='ACTIVE'?'Pasif yap':'Aktif yap'}>{x.status==='ACTIVE'?<ToggleRight size={17}/>:<ToggleLeft size={17}/>}</button>}{boot.user.id!==x.id&&<button className="danger" onClick={()=>remove(x)} title="Sil"><Trash2 size={15}/></button>}</Actions>]})}/>{edit&&<UserModal boot={boot} item={edit.id?edit:null} close={()=>setEdit(null)} saved={()=>{setEdit(null);q.reload()}}/>}{passwordUser&&<UserPasswordModal user={passwordUser} close={()=>setPasswordUser(null)} saved={()=>{setPasswordUser(null);q.reload()}}/>}</>}
function UserModal({boot,item,close,saved}:{boot:Bootstrap;item:any|null;close:()=>void;saved:()=>void}){const[b,setB]=useState<any>(item?{...item,password:''}:{role:'PERSONEL',status:'ACTIVE'});const save=async()=>{const payload={...b};if(!payload.password)delete payload.password;await api(item?`/api/users/${item.id}`:'/api/users',{method:item?'PATCH':'POST',body:JSON.stringify(payload)});saved()};return <Modal title={item?'Kullanıcıyı düzenle':'Kullanıcı oluştur'} close={close}><FormGrid><Field label="Ad Soyad"><input value={b.full_name||''} onChange={e=>setB({...b,full_name:e.target.value})}/></Field><Field label="E-posta"><input type="email" value={b.email||''} onChange={e=>setB({...b,email:e.target.value})}/></Field><Field label="Telefon"><input value={b.phone||''} onChange={e=>setB({...b,phone:e.target.value})} placeholder="05xx xxx xx xx"/></Field><Field label={item?'Yeni şifre (isteğe bağlı)':'Geçici şifre'}><input type="password" value={b.password||''} onChange={e=>setB({...b,password:e.target.value})} placeholder={item?'Boş bırakırsanız değişmez':'En az 8 karakter'}/></Field><Field label="Rol"><select value={b.role} onChange={e=>setB({...b,role:e.target.value})}><option>ADMIN</option><option>PERSONEL</option><option>OPERASYON</option><option>KURUM</option></select></Field><Field label="Durum"><select value={b.status||'ACTIVE'} onChange={e=>setB({...b,status:e.target.value})}><option value="ACTIVE">Aktif</option><option value="PASSIVE">Pasif</option></select></Field>{b.role==='KURUM'&&<Field label="Kurum"><select value={b.institution_id||''} onChange={e=>setB({...b,institution_id:e.target.value})}><option value="">Seçiniz</option>{boot.institutions.map(i=><option value={i.id} key={i.id}>{i.name}</option>)}</select></Field>}</FormGrid><ModalActions close={close} save={save}/></Modal>}
function UserPasswordModal({user,close,saved}:{user:any;close:()=>void;saved:()=>void}){const[p,setP]=useState(''),[again,setAgain]=useState('');return <Modal title={`${user.full_name} · Şifre değiştir`} close={close}><Field label="Yeni şifre"><input type="password" value={p} onChange={e=>setP(e.target.value)} autoFocus/></Field><Field label="Yeni şifre tekrar"><input type="password" value={again} onChange={e=>setAgain(e.target.value)}/></Field><ModalActions close={close} save={async()=>{if(p.length<10)throw new Error('Süper Admin şifresi en az 10 karakter olmalı.');if(p!==again)throw new Error('Şifreler eşleşmiyor.');await api(`/api/users/${user.id}`,{method:'PATCH',body:JSON.stringify({password:p})});saved()}}/></Modal>}
function PermissionsAdmin({boot}:{boot:Bootstrap}){if(boot.user.role!=='SUPER_ADMIN')return <Empty text="Kullanıcı yetkilerini yalnız Süper Admin değiştirebilir."/>;const users=useAsync(()=>api('/api/users'),[]),catalog=useAsync(()=>api('/api/permissions/catalog'),[]),[selected,setSelected]=useState(''),[allowed,setAllowed]=useState<Set<string>>(new Set()),[loaded,setLoaded]=useState(false),[msg,setMsg]=useState('');const list=((users.data as any)?.items||[]).filter((x:any)=>x.role!=='SUPER_ADMIN');useEffect(()=>{if(!selected){setLoaded(false);return}api(`/api/users/${selected}/permissions`).then(d=>{setAllowed(new Set(d.allowed||[]));setLoaded(true)})},[selected]);const items=(catalog.data as any)?.items||[];const groups=[...new Set(items.map((x:any)=>x.group))];const toggle=(c:string)=>setAllowed(v=>{const n=new Set(v);n.has(c)?n.delete(c):n.add(c);return n});const save=async()=>{await api(`/api/users/${selected}/permissions`,{method:'PUT',body:JSON.stringify({allowed:[...allowed]})});setMsg('Kullanıcı yetkileri kaydedildi. Yeni oturumda menüler ve işlemler bu yetkilere göre çalışır.')};return <><div className="permission-hero"><div><ShieldCheck/><div><h2>Kullanıcı Yetkileri</h2><p>Kullanıcının yapabileceği işleri tek tek açın veya kapatın. Süper Admin yetkileri değiştirilemez.</p></div></div><select value={selected} onChange={e=>{setSelected(e.target.value);setMsg('')}}><option value="">Kullanıcı seçin</option>{list.map((x:any)=><option key={x.id} value={x.id}>{x.full_name} · {roleName(x.role)}</option>)}</select></div>{selected&&loaded&&<>{groups.map((g:any)=><Panel title={g} icon={Lock} key={g}><div className="permission-grid">{items.filter((x:any)=>x.group===g).map((x:any)=><label className="permission-item" key={x.code}><input type="checkbox" checked={allowed.has(x.code)} onChange={()=>toggle(x.code)}/><div><b>{x.label}</b><small>{x.code}</small></div></label>)}</div></Panel>)}<button className="btn primary" onClick={save}><Save size={16}/> Yetkileri Kaydet</button>{msg&&<div className="success-box"><CheckCircle2 size={18}/>{msg}</div>}</>}</>}
function TasksAdmin({boot}:{boot:Bootstrap}){if(boot.user.role!=='SUPER_ADMIN')return <Empty text="Görev atama yetkisi yalnız Süper Admin'dedir."/>;const q=useAsync(()=>api('/api/tasks?scope=all'),[]),[modal,setModal]=useState(false);const items=(q.data as any)?.items||[];return <><Toolbar><div><b>Kullanıcı Görevleri</b><span className="muted"> · Personel, admin ve operasyon kullanıcılarına görev atayın.</span></div><div className="spacer"/><button className="btn primary" onClick={()=>setModal(true)}><Plus size={16}/> Görev Ata</button></Toolbar><DataTable cols={['Kullanıcı','Görev','Öncelik','Son Tarih','Durum']} rows={items.map((x:any)=>[x.assigned_name||'—',x.title,x.priority||'MEDIUM',fmtDate(x.due_date),<Badge key="s" text={x.status==='DONE'?'Tamamlandı':'Açık'} tone={x.status==='DONE'?'good':'warn'}/>])}/>{modal&&<TaskModal boot={boot} close={()=>setModal(false)} saved={()=>{setModal(false);q.reload()}}/>}</>}
function TaskModal({boot,close,saved}:{boot:Bootstrap;close:()=>void;saved:()=>void}){const[b,setB]=useState<any>({assigned_to:boot.staff.find(x=>x.role!=='SUPER_ADMIN')?.id||'',priority:'MEDIUM'});return <Modal title="Kullanıcıya görev ata" close={close}><FormGrid><Field label="Kullanıcı"><select value={b.assigned_to||''} onChange={e=>setB({...b,assigned_to:e.target.value})}><option value="">Seçiniz</option>{boot.staff.filter(x=>x.role!=='SUPER_ADMIN').map(x=><option key={x.id} value={x.id}>{x.full_name} · {roleName(x.role)}</option>)}</select></Field><Field label="Öncelik"><select value={b.priority} onChange={e=>setB({...b,priority:e.target.value})}><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>URGENT</option></select></Field><Field label="Görev"><input value={b.title||''} onChange={e=>setB({...b,title:e.target.value})}/></Field><Field label="Son tarih"><input type="date" value={b.due_date||''} onChange={e=>setB({...b,due_date:e.target.value})}/></Field></FormGrid><Field label="Açıklama"><textarea value={b.description||''} onChange={e=>setB({...b,description:e.target.value})}/></Field><ModalActions close={close} save={async()=>{await api('/api/tasks',{method:'POST',body:JSON.stringify(b)});saved()}}/></Modal>}
function NotificationSettings(){const q=useAsync(()=>api('/api/me/notification-settings'),[]),[phone,setPhone]=useState(''),[enabled,setEnabled]=useState(false),[msg,setMsg]=useState('');useEffect(()=>{if(q.data){setPhone((q.data as any).phone||'');setEnabled(!!(q.data as any).notification_enabled)}},[q.data]);const d:any=q.data||{};return <div className="grid-2"><Panel title="Sınav Hatırlatmaları" icon={Bell}><p className="muted">Son sipariş tarihinden 7, 3, 1 gün önce ve son gün uygulama içi bildirim oluşturulur.</p><Field label="Telefon"><input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="05xx xxx xx xx"/></Field><label className="check"><input type="checkbox" checked={enabled} onChange={e=>setEnabled(e.target.checked)}/> Harici telefon bildirimi için bu numarayı kullan</label><button className="btn primary" onClick={async()=>{await api('/api/me/notification-settings',{method:'PATCH',body:JSON.stringify({phone,notification_enabled:enabled})});setMsg('Bildirim ayarları kaydedildi.')}}><Save size={16}/> Kaydet</button>{msg&&<div className="success-box"><CheckCircle2 size={18}/>{msg}</div>}</Panel><Panel title="Telefon Bildirim Bağlantısı" icon={Phone}><div className={`integration-status ${d.phone_provider_configured?'':'muted-state'}`}>{d.phone_provider_configured?<CheckCircle2/>:<Clock3/>}<div><b>{d.phone_provider_configured?'Telefon bildirim sağlayıcısı bağlı':'Telefon sağlayıcısı henüz bağlı değil'}</b><small>{d.phone_provider_configured?'Kayıtlı numaraya harici bildirim gönderimi etkinleştirilebilir.':'Uygulama içi hatırlatmalar çalışır. SMS/WhatsApp/telefon push için bir sağlayıcı webhook bağlantısı tanımlanmalıdır.'}</small></div></div></Panel></div>}

function Seasons({boot,refreshBoot}:{boot:Bootstrap;refreshBoot:()=>Promise<void>}){const[modal,setModal]=useState<any|null>(null);const activate=async(s:any)=>{if(s.is_active)return;await api(`/api/seasons/${s.id}`,{method:'PATCH',body:JSON.stringify({is_active:true})});await refreshBoot()};return <><Toolbar><div><b>Sezon Yönetimi</b><span className="muted season-hint"> Yeni eğitim-öğretim sezonlarını buradan manuel ekleyebilirsiniz.</span></div><div className="spacer"/><button className="btn primary" onClick={()=>setModal({})}><Plus size={16}/> Yeni Sezon Ekle</button></Toolbar><div className="card-grid">{boot.seasons.map(s=><div className={`season-card ${s.is_active?'active':''}`} key={s.id}><CalendarRange/><div><h3>{s.name}</h3><p>{s.is_active?'Aktif sezon':'Geçmiş / gelecek sezon'}</p></div><Actions><button onClick={()=>setModal(s)} title="Düzenle"><Pencil size={15}/></button>{!s.is_active&&<button className="btnlike" onClick={()=>activate(s)}>Aktif Yap</button>}</Actions></div>)}</div>{modal&&<SeasonModal item={modal.id?modal:null} close={()=>setModal(null)} saved={async()=>{setModal(null);await refreshBoot()}}/>}</>}
function SeasonModal({item,close,saved}:{item:any|null;close:()=>void;saved:()=>void}){const[b,setB]=useState<any>(item?{...item}:{is_active:false});return <Modal title={item?'Sezonu düzenle':'Yeni sezon ekle'} close={close}><FormGrid><Field label="Sezon adı"><input placeholder="2027-2028" value={b.name||''} onChange={e=>setB({...b,name:e.target.value})}/></Field><Field label="Başlangıç yılı"><input type="number" value={b.year_start||''} onChange={e=>setB({...b,year_start:e.target.value})}/></Field><Field label="Bitiş yılı"><input type="number" value={b.year_end||''} onChange={e=>setB({...b,year_end:e.target.value})}/></Field></FormGrid><label className="check"><input type="checkbox" checked={!!b.is_active} onChange={e=>setB({...b,is_active:e.target.checked})}/> Aktif sezon yap</label><ModalActions close={close} save={async()=>{await api(item?`/api/seasons/${item.id}`:'/api/seasons',{method:item?'PATCH':'POST',body:JSON.stringify(b)});saved()}}/></Modal>}
function Integration(){const db=useAsync(()=>api('/api/setup/status'),[]),erp=useAsync(()=>api('/api/erp/status'),[]);return <div className="grid-2"><Panel title="Cloudflare D1" icon={Warehouse}><div className="integration-status"><CheckCircle2/><div><b>{(db.data as any)?.database?'D1 bağlı':'D1 gerekli'}</b><small>{(db.data as any)?.version||''}</small></div></div></Panel><Panel title="YILDIZERP" icon={RefreshCw}><div className={`integration-status ${(erp.data as any)?.configured?'':'muted-state'}`}>{(erp.data as any)?.configured?<CheckCircle2/>:<Clock3/>}<div><b>{(erp.data as any)?.configured?'ERP bağlantısı yapılandırıldı':'ERP isteğe bağlı / manuel kullanım aktif'}</b><small>{(erp.data as any)?.base_url||'ERP bağlantısı olmasa da kurumlar manuel oluşturulabilir.'}</small></div></div></Panel></div>}

// UI HELPERS
function Toolbar({children}:{children:any}){return <div className="toolbar">{children}</div>}
function SearchBox({value,set}:{value:string;set:(x:string)=>void}){return <label className="search"><Search size={16}/><input placeholder="Ara…" value={value} onChange={e=>set(e.target.value)}/></label>}
function DataTable({cols,rows}:{cols:string[];rows:any[][]}){return <div className="table-wrap"><table><thead><tr>{cols.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j}>{v}</td>)}</tr>)}</tbody></table>{!rows.length&&<Empty text="Kayıt bulunamadı."/>}</div>}
function Actions({children}:{children:any}){return <div className="row-actions">{children}</div>}
function Badge({text,tone='info'}:{text:string;tone?:string}){return <span className={`badge ${tone}`}>{text}</span>}
function Empty({text}:{text:string}){return <div className="empty"><CalendarDays/><p>{text}</p></div>}
function Loading(){return <div className="loading"><RefreshCw className="spin"/> Yükleniyor…</div>}
function ErrorState({text,retry}:{text:string;retry:()=>void}){return <div className="error-state"><AlertTriangle/><b>{text}</b><button className="btn" onClick={retry}>Tekrar dene</button></div>}
function Modal({title,close,children}:{title:string;close:()=>void;children:any}){return <div className="modal-back" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div className="modal"><div className="modal-head"><h2>{title}</h2><button className="icon-btn" onClick={close}><X/></button></div>{children}</div></div>}
function FormGrid({children}:{children:any}){return <div className="form-grid">{children}</div>}
function Field({label,children}:{label:string;children:any}){return <label className="field"><span>{label}</span>{children}</label>}
function ModalActions({close,save}:{close:()=>void;save:()=>void|Promise<void>}){const[busy,setBusy]=useState(false),[err,setErr]=useState('');return <>{err&&<div className="error-box">{err}</div>}<div className="modal-actions"><button className="btn" onClick={close}>Vazgeç</button><button className="btn primary" disabled={busy} onClick={async()=>{setBusy(true);setErr('');try{await save()}catch(e:any){setErr(e.message)}finally{setBusy(false)}}}><Save size={16}/>{busy?'Kaydediliyor…':'Kaydet'}</button></div></>}

